_G["StoryInfo"]={[10134]={["key"]=10134,["storyType"]=1,["name"]="第一章-第32节",["beginId"]=1013401,["id"]=10134,["type"]=1,["section_name"]="禮物",["desc"]="敗給阿爾卑斯和雅典娜的赫拉如釋重負，清楚地明白了自己究竟想要什麼，現在她將送出她的禮物。"}
,[21307]={["key"]=21307,["storyType"]=15,["name"]="魔导少女活动剧情6",["beginId"]=2130701,["id"]=21307,["type"]=1,["section_name"]="深入敵營（上）",["desc"]="眾人一邊深入造物工廠，一邊聊著關於《魔法少女小葉》的話題。伊根為了儘快救出其他人，拒絕了維護魔導晶管的要求。而刺蝽也把自己察覺到的奇怪之處告訴了總隊長。"}
,[20300]={["key"]=20300,["storyType"]=5,["name"]="袅韵个人活动1",["beginId"]=2030001,["id"]=20300,["type"]=1,["section_name"]="開端",["desc"]="裊韻與神秘的夥伴進行了雨夜密談。"}
,[21403]={["key"]=21403,["storyType"]=16,["name"]="冬日速递2",["beginId"]=2140301,["id"]=21403,["type"]=1,["section_name"]="護送任務（上）",["desc"]="卡蒂雅需要你護衛梅尼的同時調查神秘造物，你還邀請赫格尼一起執行這個任務。赫格尼接受之後，突然出現的洛基表示自己也想參加。"}
,[10206]={["key"]=10206,["storyType"]=1,["name"]="第二章-第3节",["beginId"]=1020601,["id"]=10206,["type"]=1,["section_name"]="墜落地",["desc"]="總隊長與普羅米修斯迫降在板塊上，在那裡等著他們的是成群的造物。"}
,[10214]={["key"]=10214,["storyType"]=1,["name"]="第二章-第7节",["beginId"]=1021401,["id"]=10214,["type"]=1,["section_name"]="保護傘",["desc"]="洛基被伊瓦爾迪推舉為戰區執政官，以建立起連接兩個戰區的橋樑。"}
,[20428]={["key"]=20428,["storyType"]=6,["name"]="糖果活动剧情29",["beginId"]=2042801,["id"]=20428,["type"]=1,["section_name"]="結局未知（下）",["desc"]="伴隨著索爾達森的倒下，投影散去，之見破敗的前哨基地。"}
,[10238]={["key"]=10238,["storyType"]=1,["name"]="第二章-第20节",["beginId"]=1023801,["id"]=10238,["type"]=1,["section_name"]="破局人",["desc"]="自知不敵的格恩達爾決心與布倫希爾德玉石俱焚，趕來的女武神部隊阻止了兩人的戰鬥。"}
,[10246]={["key"]=10246,["storyType"]=1,["name"]="第二章-第25节",["beginId"]=1024601,["id"]=10246,["type"]=1,["section_name"]="殊死戰",["desc"]="人類與造物的大戰一觸即發。"}
,[10254]={["key"]=10254,["storyType"]=1,["name"]="第二章-第33节",["beginId"]=1025401,["id"]=10254,["type"]=1,["section_name"]="電子躍遷",["desc"]="來歷不明的人物阻撓了探索隊的行動。世界樹外，洛基和絲卡蒂的戰鬥被強制中斷。"}
,[20508]={["key"]=20508,["storyType"]=7,["name"]="夏日海韵活动剧情7",["beginId"]=2050801,["id"]=20508,["type"]=1,["section_name"]="釣客清話（上）",["desc"]="在資深釣客槍棘的指導下，一心苦惱給新故事取材的布爾特根釣上了一個意料之外的“大家夥”。"}
,[21611]={["key"]=21611,["storyType"]=18,["name"]="意欲地牢6",["beginId"]=2161101,["id"]=21611,["type"]=1,["section_name"]="過去之影（上）",["desc"]="在經過簡單的修整後，你們決定這一次由瑞絲開門。而這一次展現在你們面前的，是一片祥和的郊外森林。"}
,[20604]={["key"]=20604,["storyType"]=8,["name"]="幻梦逸旅活动剧情5",["beginId"]=2060401,["id"]=20604,["type"]=1,["section_name"]="門裡，門外（上）",["desc"]="離開地下空間的路上，C.C.C.提議乾脆拆牆離開，總隊長表示不需要，自己提前備份了廠房的設計佈局圖，知道該怎麼走。走到某條過道時溫蒂聽到求救聲，眾人發現求救的是溫蒂失蹤的朋友薇露卡。"}
,[10318]={["key"]=10318,["storyType"]=1,["name"]="第三章-第14节",["beginId"]=1031801,["id"]=10318,["type"]=1,["section_name"]="遺民之爭（下）",["desc"]="被總隊長和刃齒等人擊敗的穆特不願接受失敗，召出了能不斷吸收其他殘片和核心碎片的融合造物。在這個時候，信風和閃鋅正好趕到。"}
,[10326]={["key"]=10326,["storyType"]=1,["name"]="第三章-第21节",["beginId"]=1032601,["id"]=10326,["type"]=1,["section_name"]="一觸即發（下）",["desc"]="總隊長等人被失控的造物包圍，而且還有更多造物正在趕來。為了攔阻越來越多的失控造物，閃鋅和信風設下了多種攔阻。"}
,[10334]={["key"]=10334,["storyType"]=1,["name"]="第三章-第28节",["beginId"]=1033401,["id"]=10334,["type"]=1,["section_name"]="不按常理（下）",["desc"]="按照奧西裏斯所說的通路，眾人來到尼克羅的軌道電梯前。普羅米修斯判斷軌道電梯與「冥界」系統、收束塔都有著緊密聯系，一旦破壞其中一個，都會導致不可挽回的後果。"}
,[10342]={["key"]=10342,["storyType"]=1,["name"]="第三章-第36节",["beginId"]=1034201,["id"]=10342,["type"]=1,["section_name"]="高空翱翔（下）",["desc"]="暫時清除了失控造物後，總隊長和普羅米修斯再次提起異變，瑪哈特好奇詢問總隊長來到尼克羅的原因，總隊長告知她，自己既然是探索隊的隊長，就有了相應要背負的責任。"}
,[10350]={["key"]=10350,["storyType"]=1,["name"]="第三章-第44节",["beginId"]=1035001,["id"]=10350,["type"]=1,["section_name"]="最終護衛（上）",["desc"]="進入收束塔後，刃齒詢問總隊長之前的經歷，感嘆沒能和碎星人好好打上幾場，活動得不夠徹底。總隊長表示之後會讓第三分隊和之前救回的分隊前往其他板塊搜尋隊員，不會讓刃齒感到無聊。"}
,[20700]={["key"]=20700,["storyType"]=9,["name"]="奇迹之夜活动剧情1",["beginId"]=2070001,["id"]=20700,["type"]=1,["section_name"]="歸鄉騎士",["desc"]="神秘的NOVA能量導致卡洲異變事件頻發，總隊長收到咎瓦尤斯邀請，利用假期返回地球調查此事，尼克羅的使者拉也一道隨行。"}
,[20716]={["key"]=20716,["storyType"]=9,["name"]="奇迹之夜活动剧情16",["beginId"]=2071601,["id"]=20716,["type"]=1,["section_name"]="幕前插曲",["desc"]="世界即舞臺，舞臺即戰場，在最終的謝幕到來之前，請接收如雷的掌聲，盡情展現最無畏的英姿吧。"}
,[21803]={["key"]=21803,["storyType"]=20,["name"]="筑梦热土3",["beginId"]=2180301,["id"]=21803,["type"]=1,["section_name"]="澡盆裏的入侵者（上）",["desc"]="結束了疲憊的一天，卡提那獨自回到臥室。等待她的除了夥伴們的關心，還有……"}
,[10406]={["key"]=10406,["storyType"]=1,["name"]="第四章-第5节",["beginId"]=1040601,["id"]=10406,["type"]=1,["section_name"]="清理工序（下）",["desc"]="希恩離開後，鳴刃對總隊長的戰力頗感興趣，想要和總隊長交手。總隊長無奈答應，鳴刃認為用合適的武器與總隊長對戰才能表示對這場戰鬥的尊重，帶領總隊長返回自己的住所，尋找備用武器。"}
,[10414]={["key"]=10414,["storyType"]=1,["name"]="第四章-第13节",["beginId"]=1041401,["id"]=10414,["type"]=1,["section_name"]="無形之手（上）",["desc"]="旋律被過往所纏繞，深陷於噩夢中。第五分隊其他人為旋律的情況憂心，勸慰旋律。總隊長這邊，總隊長拋出己方對「研者」的相關資料，以此換取天階原收束塔的資料。"}
,[10422]={["key"]=10422,["storyType"]=1,["name"]="第四章-第20节",["beginId"]=1042201,["id"]=10422,["type"]=1,["section_name"]="聯結實驗（上）",["desc"]="熔鑠尋找鳴刃途中遇到大批感染造物，發現所有通訊頻道都靜默了，對此極為驚詫，想要趕往居民區開啟防禦系統。總隊長與鳴刃見到歲稔後卻發現歲稔重拾了「研者」的研究。"}
,[10430]={["key"]=10430,["storyType"]=1,["name"]="第四章-第27节",["beginId"]=1043001,["id"]=10430,["type"]=1,["section_name"]="異變之始（下）",["desc"]="順利關閉管道閥門後，鳴刃和總隊長正準備前去收束塔，卻遇到了異變後的熔鑠。"}
,[10438]={["key"]=10438,["storyType"]=1,["name"]="第四章-第34节",["beginId"]=1043801,["id"]=10438,["type"]=1,["section_name"]="隱藏真相（上）",["desc"]="總隊長與鳴刃在收束塔下遇到了等候的赤夕，異變後的赤夕要求兩人與自己戰鬥，記錄下關於異變者戰鬥時的數據。"}
,[10446]={["key"]=10446,["storyType"]=1,["name"]="第四章-第42节",["beginId"]=1044601,["id"]=10446,["type"]=1,["section_name"]="未來繪景（上）",["desc"]="進入核心天使所在的收束塔區域，看到的卻是超出想像的奇異機械造物。在與該機械生命體交談後，機械生命體自稱是「系爾」，借助這個機械造物的軀體與總隊長交流。在交談過後，「系爾」與總隊長達成合作。"}
,[21915]={["key"]=21915,["storyType"]=21,["name"]="异态侵蚀9",["beginId"]=2191501,["id"]=21915,["type"]=1,["section_name"]="意外（下）",["desc"]="安保機器人並沒有襲擊眾人，而是開始控制喪失理智的安保人員。然而就在這時，安保機器人再次發生變化向妮娜撲去。維拉捨身相救導致自己受傷，無法行動的她決定掩護眾人留下斷後。"}
,[20908]={["key"]=20908,["storyType"]=11,["name"]="云端行迹活动剧情9",["beginId"]=2090801,["id"]=20908,["type"]=1,["section_name"]="塔中記載（上）",["desc"]="總隊長與朝暉在雙衍之塔中找到了失散的閃電，閃電告訴總隊長自己受白鳥的請托，幫忙與雙衍之塔的意識幻覺對戰，讓負責修復程式的涅毒不至於遭遇危險。"}
,[10510]={["key"]=10510,["storyType"]=1,["name"]="第五章-第8节",["beginId"]=1051001,["id"]=10510,["type"]=1,["section_name"]="長夜不寧（上）",["desc"]="審計司司長塞萊斯汀臨時受命帶走總隊長並組建危機干預小組，在等候其他成員趕到時，維羅妮卡告知只有昆侖的新武裝可以打破稽查者的防禦，但蓄能時間極長，需要儘量拖延時間。"}
,[10518]={["key"]=10518,["storyType"]=1,["name"]="第五章-第14节",["beginId"]=1051801,["id"]=10518,["type"]=1,["section_name"]="基地週邊（上）",["desc"]="總隊長挑釁稽查者，稽查者暴怒下召喚了附近的機械造物。"}
,[10526]={["key"]=10526,["storyType"]=1,["name"]="第五章-第22节",["beginId"]=1052601,["id"]=10526,["type"]=1,["section_name"]="引導行動（上）",["desc"]="桑格維斯幫的成員找到了負責重建工程的建築商夏洛特，從她那獲得了卡洲及維洲城鎮的重建圖紙，還從療養院找到了曾經擔任阿卡斯助手的布蕾雅女士的日記。"}
,[10534]={["key"]=10534,["storyType"]=1,["name"]="第五章-第30节",["beginId"]=1053401,["id"]=10534,["type"]=1,["section_name"]="暗藍之願（下）",["desc"]="伊德海拉發現總隊長及巨浪脫離監控後大怒，向滄發難。滄與伊德海拉爭執，霍華德從中調停。"}
,[10542]={["key"]=10542,["storyType"]=1,["name"]="第五章-第38节",["beginId"]=1054201,["id"]=10542,["type"]=1,["section_name"]="漸見前路",["desc"]="洛貝拉用譏諷的話語刺激產生自我懷疑的昆侖，實則是借用總隊長的話來開導昆侖。從海底探查後回歸的巨浪似乎遭遇了某種事情，記憶逐漸消散。"}
,[21100]={["key"]=21100,["storyType"]=13,["name"]="虚海奇谭活动剧情1",["beginId"]=2110001,["id"]=21100,["type"]=1,["section_name"]="海濱邂逅",["desc"]="總隊長掉入資料海，感覺自己的意識正在遠去。危急關頭，名為“提澤納”的女性將總隊長從資料海救起，並且一同找到失散的哈托莉。"}
,[20109]={["key"]=20109,["storyType"]=2,["name"]="卡提那个人活动第10节",["beginId"]=2010901,["id"]=20109,["type"]=1,["section_name"]="逃離",["desc"]="從宙斯的威壓下逃離的奧巴瑟一言不發，只想前往總隊長消失的地方，尋找總隊長的蹤跡。"}
,[10606]={["key"]=10606,["storyType"]=1,["name"]="第六章-第3节",["beginId"]=1060601,["id"]=10606,["type"]=1,["section_name"]="雪域荒城（下）",["desc"]="神秘武裝少女自稱“阿萊西婭”，並說與總隊長有著深仇。總隊長想從她那獲取關於阿卡斯及“索菲亞之瞳”的情報，此時阿萊西婭的同伴出現。"}
,[10614]={["key"]=10614,["storyType"]=1,["name"]="第六章-第8节",["beginId"]=1061401,["id"]=10614,["type"]=1,["section_name"]="苔原燭光（上）",["desc"]="希恩離開據點後意外遇到難民們的管理者斯維特蘭娜，並跟著她去到了維利卡聚居點。而總隊長這邊與洛貝拉交流北境戰區的情況時，發現了意外的線索。"}
,[10622]={["key"]=10622,["storyType"]=1,["name"]="第六章-第14节",["beginId"]=1062201,["id"]=10622,["type"]=1,["section_name"]="真實身份（下）",["desc"]="擊敗了來襲的造物後，翼蓑將泰坦級造物核心交給總隊長，告訴總隊長可以使用高等造物的核心反向追溯來源。"}
,[10630]={["key"]=10630,["storyType"]=1,["name"]="第六章-第22节",["beginId"]=1063001,["id"]=10630,["type"]=1,["section_name"]="深入密巢（下）",["desc"]="進入茲梅伊密巢後後，總隊長等人選擇直接破拆至對應座標。而在基地裏，洛貝拉將控制臺交給薩斯塔控制，薩斯塔表示自己擔心洛貝拉的狀態，洛貝拉略微柔和表示不需要擔心自己。"}
,[10638]={["key"]=10638,["storyType"]=1,["name"]="第六章-第29节",["beginId"]=1063801,["id"]=10638,["type"]=1,["section_name"]="過往難追（上）",["desc"]="莫羅斯基地的人為難民們帶來了資源，難民們舉行了慶祝晚宴，希恩第一次真正接觸了人性的溫暖。在希恩離開後，在阿卡斯的蠱惑下，彌鈴帶領造物對聚居點進行了屠戮。"}
,[10646]={["key"]=10646,["storyType"]=1,["name"]="第六章-第33节",["beginId"]=1064601,["id"]=10646,["type"]=1,["section_name"]="深海脈動（下）",["desc"]="在擊敗埋伏的機械造物後，總隊長再次被拉入幻覺中，看到了無比奇異的畫面。在看到一個怪異陰影後，總隊長被迫醒來，發現跟前的並合開關似乎就要徹底聯通，於是驅使漆黑擊毀了開關。"}
,[21308]={["key"]=21308,["storyType"]=15,["name"]="魔导少女活动剧情7",["beginId"]=2130801,["id"]=21308,["type"]=1,["section_name"]="深入敵營（下）",["desc"]="伊根在戰鬥中出現了異樣，但被她搪塞過去。總隊長與其溝通確認沒問題後，眾人再次深入造物工廠。"}
,[20301]={["key"]=20301,["storyType"]=5,["name"]="袅韵个人活动2",["beginId"]=2030101,["id"]=20301,["type"]=1,["section_name"]="不歡而散的對話",["desc"]="在一場與基因學會代表的直播對話中，裊韻被當場指控涉嫌學術造假。"}
,[21404]={["key"]=21404,["storyType"]=16,["name"]="冬日速递3",["beginId"]=2140401,["id"]=21404,["type"]=1,["section_name"]="護送任務（下）",["desc"]="眾人剛來戈里刻板塊，立刻就遇到了失控造物。在解決失控造物後，戈里刻的雅典娜出現在眾人面前。"}
,[20413]={["key"]=20413,["storyType"]=6,["name"]="糖果活动剧情14",["beginId"]=2041301,["id"]=20413,["type"]=1,["section_name"]="無法暫停（上）",["desc"]="渦流準備前往尼約姆，卻落入宇宙刑警赫爾墨斯的陷阱之中。"}
,[20429]={["key"]=20429,["storyType"]=6,["name"]="糖果活动剧情30",["beginId"]=2042901,["id"]=20429,["type"]=1,["section_name"]="幕後余聲",["desc"]="這場演出過後，似乎一切都沒有改變，又似乎有了改變。劇本還在手中，未來亟待書寫。"}
,[21500]={["key"]=21500,["storyType"]=17,["name"]="裂空活动1",["beginId"]=2150001,["id"]=21500,["type"]=1,["section_name"]="日出之後",["desc"]="艾格強行為你放了個長假。“遺忘之地”凱邁特，所謂的旅行怎麼看都更像是流放。不過名為裂空的搭檔對此興致滿滿，算了，走一步看一步吧。"}
,[20509]={["key"]=20509,["storyType"]=7,["name"]="夏日海韵活动剧情8",["beginId"]=2050901,["id"]=20509,["type"]=1,["section_name"]="釣客清話（下）",["desc"]="雖然比故事更離譜的現實經歷遭到了赤溟的質疑，但槍棘的海釣興致不減，布爾特根的苦惱也得到了總隊長的開導，真是可喜可賀。"}
,[20605]={["key"]=20605,["storyType"]=8,["name"]="幻梦逸旅活动剧情6",["beginId"]=2060501,["id"]=20605,["type"]=1,["section_name"]="門裡，門外（下）",["desc"]="打敗圍困薇露卡的造物後，C.C.C.教訓薇露卡和溫蒂，言語逐漸尖刻。總隊長想要調停，勸解C.C.C.也是想幫助兩個小孩子，為什麼要用這麼尖銳的言語。C.C.C.聽到後想起自己的過往，瞬間憤怒，攜帶的無人機也開啟攻擊狀態。"}
,[21708]={["key"]=21708,["storyType"]=19,["name"]="假日共游8",["beginId"]=2170801,["id"]=21708,["type"]=1,["section_name"]="聲東擊西（上）",["desc"]="歲稔來到露天百貨商場，恰好遇到大批造物湧入商場擄走人類，歲稔為了保護市民主動攻擊造物，卻被帶有特殊能力的造物所傷。"}
,[20701]={["key"]=20701,["storyType"]=9,["name"]="奇迹之夜活动剧情2",["beginId"]=2070101,["id"]=20701,["type"]=1,["section_name"]="偷渡客（上）",["desc"]="思鄉心切的星椋也混進了飛行倉一同來到了地球，然而本該接應的卡洲第十三調查局卻行跡詭異。"}
,[21804]={["key"]=21804,["storyType"]=20,["name"]="筑梦热土4",["beginId"]=2180401,["id"]=21804,["type"]=1,["section_name"]="澡盆裏的入侵者（下）",["desc"]="驅退了入侵的造物，你們決定憑藉有限的資源提升居住點的防衛。與此同時，阿圖姆終於聯繫上了阿努比斯……"}
