,[10103]={["key"]=10103,["storyType"]=1,["name"]="第一章-第3节",["beginId"]=1010301,["id"]=10103,["type"]=1,["section_name"]="隊員",["desc"]="即便強度不高，也不足以構成生命威脅，但依舊使人心倦。而在灰暗的光景下卻也發現了隊員的行蹤，現在，支援隊員——赤狼。"}
,[10111]={["key"]=10111,["storyType"]=1,["name"]="第一章-第9节",["beginId"]=1011101,["id"]=10111,["type"]=1,["section_name"]="蛹室",["desc"]="結冰深谷上，雅典娜和阿爾卑斯丟下最後一批蛹室，正準備前往尋找%s一行，卻發現眾人已經走入了阿瑞斯的陷阱之中。"}
,[10119]={["key"]=10119,["storyType"]=1,["name"]="第一章-第17节",["beginId"]=1011901,["id"]=10119,["type"]=1,["section_name"]="要脅",["desc"]="身為信使的赫爾墨斯利用地球人的安危“要脅”%s饒自己一命，不懂地球人交流方式的她還不知道未來將要面對的是什麼。"}
,[10127]={["key"]=10127,["storyType"]=1,["name"]="第一章-第25节",["beginId"]=1012701,["id"]=10127,["type"]=1,["section_name"]="異路",["desc"]="突然改變計畫的安第斯最終選擇了和哈迪斯提供的地點相反的方向，現在必須立刻趕過去。"}
