,[20510]={["key"]=20510,["storyType"]=7,["name"]="夏日海韵活动剧情9",["beginId"]=2051001,["id"]=20510,["type"]=1,["section_name"]="爆裂衝浪手（上）",["desc"]="極限運動愛好者的天職就是挑戰大海！然而在飲下了白蛉醫師的特製運動飲料後，活力滿滿的沼波被長腳的救生椅劫持，消失在了海灘深處。"}
,[21613]={["key"]=21613,["storyType"]=18,["name"]="意欲地牢7",["beginId"]=2161301,["id"]=21613,["type"]=1,["section_name"]="過去之影（下）",["desc"]="房間並沒有展示出瑞絲的慾望，只是展示出瑞絲居住過的別墅。瑞絲藉機把自己的過往告訴給了大家。"}
,[10311]={["key"]=10311,["storyType"]=1,["name"]="第三章-第7节",["beginId"]=1031101,["id"]=10311,["type"]=1,["section_name"]="未知區域（上）",["desc"]="白衣少女來到尼克羅的收束塔中，開啟了異變。另一邊，總隊長與普羅米修斯路過冷凍艙片區，討論如果突然斷開能量流，艙中的碎星人會變成什麽樣。"}
,[10319]={["key"]=10319,["storyType"]=1,["name"]="第三章-第15节",["beginId"]=1031901,["id"]=10319,["type"]=1,["section_name"]="自我認知",["desc"]="荷魯斯與普羅米修斯因為瑪哈特而發生口角，瑪哈特情緒爆發，憤怒表示自己與阿圖姆完全不同，繼而跑開。總隊長找到獨自待著的瑪哈特後，開解瑪哈特。"}
,[10327]={["key"]=10327,["storyType"]=1,["name"]="第三章-第22节",["beginId"]=1032701,["id"]=10327,["type"]=1,["section_name"]="長夜夢醒（上）",["desc"]="順利到達指揮中心後，普羅米修斯嘗試向阿努比斯發起聯絡，但發現指揮中心的系統被暴力入侵，無法使用。而且守護指揮中心的造物守衛也進入了失控狀態。"}
,[10335]={["key"]=10335,["storyType"]=1,["name"]="第三章-第29节",["beginId"]=1033501,["id"]=10335,["type"]=1,["section_name"]="正午烈陽（上）",["desc"]="總隊長等人在登上軌道電梯前被自稱「拉」的碎星人攔住，拉聲稱自己是受了阿努比斯的請求，來考驗眾人的實力。"}
,[10343]={["key"]=10343,["storyType"]=1,["name"]="第三章-第37节",["beginId"]=1034301,["id"]=10343,["type"]=1,["section_name"]="洶湧如潮（上）",["desc"]="到達軌道電梯頂部後，瑪哈特詢問是否在見過阿努比斯後，總隊長和其他人就要離開尼克羅，總隊長給予肯定回答。瑪哈特聽到後感覺難過，分隊隊員們和普羅米修斯勸慰瑪哈特。"}
,[10351]={["key"]=10351,["storyType"]=1,["name"]="第三章-第45节",["beginId"]=1035101,["id"]=10351,["type"]=1,["section_name"]="最終護衛（下）",["desc"]="順利擊敗異變的機械天使後，總隊長感嘆沒有遇到碎星稽查者，否則可以嘗試從她們那嘗試獲取收束塔的線索。眾人離開收束塔後，看到正在等候的瑪哈特與荷魯斯。"}
,[20702]={["key"]=20702,["storyType"]=9,["name"]="奇迹之夜活动剧情3",["beginId"]=2070201,["id"]=20702,["type"]=1,["section_name"]="偷渡客（下）",["desc"]="約定的匯合地點不見拉與星椋的身影，然而在晦暗的月色下，總隊長邂逅了星椋口中已故的舊友，自稱占卜魔女的西爾維婭。"}
,[21805]={["key"]=21805,["storyType"]=20,["name"]="筑梦热土5",["beginId"]=2180501,["id"]=21805,["type"]=1,["section_name"]="開拓！向著原野",["desc"]="開拓日！向著未知的荒野，前進吧！"}
,[10407]={["key"]=10407,["storyType"]=1,["name"]="第四章-第6节",["beginId"]=1040701,["id"]=10407,["type"]=1,["section_name"]="往昔記憶（上）",["desc"]="天階原居民區內，護衛隊遇到感染病毒的造物，隊長雪華對此有所疑慮，但並未多想。而鳴刃這邊在翻找許久後，終於找到了自己的備用武器。"}
,[10415]={["key"]=10415,["storyType"]=1,["name"]="第四章-第14节",["beginId"]=1041501,["id"]=10415,["type"]=1,["section_name"]="無形之手（下）",["desc"]="幫助熔鑠測試完新的造物守衛性能後，鳴刃自告奮勇帶領總隊長前往居民區，尋找失散的第五分隊。"}
,[10423]={["key"]=10423,["storyType"]=1,["name"]="第四章-第21节",["beginId"]=1042301,["id"]=10423,["type"]=1,["section_name"]="聯結實驗（下）",["desc"]="鳴刃透過仿生體與歲稔交流，嘗試讓她停下實驗，但並無效果。為了防止實驗體被啟動，需要關閉兩條運輸NOVA能量的管道，總隊長將關閉其中一條管道的任務交給了第五分隊。"}
,[10431]={["key"]=10431,["storyType"]=1,["name"]="第四章-第28节",["beginId"]=1043101,["id"]=10431,["type"]=1,["section_name"]="忘卻留聲",["desc"]="打敗異變熔鑠後，熔鑠短暫清醒過來，並告知了自己產生異變後的感受，讓總隊長和鳴刃離開前把自己捆起來，避免追上兩人。第五分隊在前往任務目的地時，異變造物大批量增加，女王蜂打算在完成任務後借助地下防禦工事快速返回居民區。"}
,[10439]={["key"]=10439,["storyType"]=1,["name"]="第四章-第35节",["beginId"]=1043901,["id"]=10439,["type"]=1,["section_name"]="隱藏真相（下）",["desc"]="戰鬥後短暫清醒的赤夕將「研者」瑪勒絲沒能離開天階原的真相告知總隊長，並說自己擁有的資訊絕對是總隊長目前最需要的。第五分隊也成功與總隊長在塔下匯合，總隊長請求鳴刃授權讓第五分隊也能進入收束塔，鳴刃在授權時發現收束塔程式被強行改寫過。"}
,[10447]={["key"]=10447,["storyType"]=1,["name"]="第四章-第43节",["beginId"]=1044701,["id"]=10447,["type"]=1,["section_name"]="未來繪景（下）",["desc"]="擊敗機械生命體後，女王蜂與總隊長交談，詢問總隊長是否發現了自己藏在基地裏的東西。總隊長回答自己確實發現了，並且也有了應對的計劃，但女王蜂等人的任務是輔助卡蒂雅，完成最初也是唯一的目標——除掉降臨到地球的機械天使、造物的源頭。"}
,[21917]={["key"]=21917,["storyType"]=21,["name"]="异态侵蚀11",["beginId"]=2191701,["id"]=21917,["type"]=1,["section_name"]="直覺（下）",["desc"]="眾人成功擊退來襲的安保機器人。戰鬥結束後，總隊長把沒說完的話說了出來。皮洛可聽了備受鼓舞，同時也進一步確認自己的心意。"}
,[20910]={["key"]=20910,["storyType"]=11,["name"]="云端行迹活动剧情11",["beginId"]=2091001,["id"]=20910,["type"]=1,["section_name"]="月色如詩（上）",["desc"]="總隊長、閃電和朝暉與其他人匯合，由於過往創傷而留有陰影的白鰭狠狠教訓了閃電，總隊長試圖調和但也被白鰭開始說教。等白鰭冷靜後，夜暝說自己找到了第四枚晶片，而朝暉也把自己在雙衍之塔內看到的部分資料內容說出。夜暝更加懷疑眾人的目的。"}
,[10503]={["key"]=10503,["storyType"]=1,["name"]="第五章-第2节",["beginId"]=1050301,["id"]=10503,["type"]=1,["section_name"]="暮色如鏽（上）",["desc"]="偽裝成NERI人員的神秘女性關注總隊長及黑石軍事基地的情況，總隊長與NSS人員僵持時，滄及時趕到，進行調停。"}
,[21006]={["key"]=21006,["storyType"]=12,["name"]="朝花夕誓活动剧情7",["beginId"]=2100601,["id"]=21006,["type"]=1,["section_name"]="期盼著的（上）",["desc"]="叢林中出現的昆蟲造物越來越多，銀羽終於明白它們原來一直依靠保護色躲藏在眾人身邊。冷靜下來後，銀羽選擇與這些昆蟲造物交戰。"}
