,[10543]={["key"]=10543,["storyType"]=1,["name"]="第五章-第39节",["beginId"]=1054301,["id"]=10543,["type"]=1,["section_name"]="最終一擊（上）",["desc"]="總隊長回到危機干預小組眾人身邊，而此時昆侖的武裝蓄能也已完成，稽查者的防禦力場正在崩潰。維羅妮卡讓總隊長等人抓住機會，徹底擊破防禦力場。"}
,[21102]={["key"]=21102,["storyType"]=13,["name"]="虚海奇谭活动剧情2",["beginId"]=2110201,["id"]=21102,["type"]=1,["section_name"]="反抗軍（上）",["desc"]="提澤納向總隊長說明伊盧森島的情況——想要回到現實世界，就只能消滅統治這裡的女王和她麾下的四天王。之後眾人找到了正在戰鬥的米伽洛，並且發現有兩名陌生的女性在與她並肩作戰。"}
