,[20512]={["key"]=20512,["storyType"]=7,["name"]="夏日海韵活动剧情11",["beginId"]=2051201,["id"]=20512,["type"]=1,["section_name"]="克拉肯的陰影",["desc"]="在碎星人研究員留下的手跡中得知，覆蓋整個板塊的海洋均是NOVA能量的擬態，甚至擁有獨立的意識，感到忌憚的碎星人留下了巨型造物克拉肯。"}
,[10304]={["key"]=10304,["storyType"]=1,["name"]="第三章-第2节",["beginId"]=1030401,["id"]=10304,["type"]=1,["section_name"]="無過往之人（上）",["desc"]="總隊長與普羅米修斯順利降落，普羅米修斯卻發現尼克羅板塊與記憶中的狀態相去甚遠。兩人不慎落入流沙，逃離時進入一個隱蔽房間。"}
,[20608]={["key"]=20608,["storyType"]=8,["name"]="幻梦逸旅活动剧情9",["beginId"]=2060801,["id"]=20608,["type"]=1,["section_name"]="真相之後（下）",["desc"]="擊敗巨型造物後，C.C.C.好奇湊過去看，沒想到造物突然暴起襲擊，總隊長拉開C.C.C.，向造物手爪和胸腔的核心位置射擊，徹底讓巨型造物失去活動能力。總隊長教訓C.C.C.、G.G.G.和幻響等人，必須學會自保而不是盲目進攻和沉迷戰鬥。"}
,[10328]={["key"]=10328,["storyType"]=1,["name"]="第三章-第23节",["beginId"]=1032801,["id"]=10328,["type"]=1,["section_name"]="長夜夢醒（下）",["desc"]="來到指揮中心的奧西裏斯在見到瑪哈特後，要求瑪哈特回到自己身邊，不能和異邦人有過多接觸。瑪哈特拒絕，奧西裏斯想強製將她帶走。"}
,[10336]={["key"]=10336,["storyType"]=1,["name"]="第三章-第30节",["beginId"]=1033601,["id"]=10336,["type"]=1,["section_name"]="正午烈陽（下）",["desc"]="總隊長打敗拉後，拉滿意離開。影突然在拉身後出現，聲稱要借用拉的軀體，並突然襲擊拉。在拉暈倒後，名為奈芙蒂斯的意識接管了拉的軀體。"}
,[10344]={["key"]=10344,["storyType"]=1,["name"]="第三章-第38节",["beginId"]=1034401,["id"]=10344,["type"]=1,["section_name"]="洶湧如潮（下）",["desc"]="失控造物的戰鬥欲望和攻擊由於吸收了NOVA能量而變得更強，眾人的彈藥數逐漸不足，體力也有所消耗。總隊長提出讓自己留在這裏，其他隊員們先離開，被普羅米修斯斥責。"}
,[10352]={["key"]=10352,["storyType"]=1,["name"]="第三章-第46节",["beginId"]=1035201,["id"]=10352,["type"]=1,["section_name"]="繼往前路",["desc"]="尼克羅為慶祝居民的清醒而舉辦了宴會，總隊長、普羅米修斯看著分隊隊員們打打鬧鬧。另一邊，影帶著載有奈芙蒂斯意識的模塊離開，並感嘆程式生成的疊代模型，到底是否算是生命的延續呢？"}
,[20704]={["key"]=20704,["storyType"]=9,["name"]="奇迹之夜活动剧情5",["beginId"]=2070401,["id"]=20704,["type"]=1,["section_name"]="魔女與笑匠（下）",["desc"]="星椋在關鍵時刻現身幫忙，在擊退了試圖刁難的調查局人員後，馬戲團團長向你伸出了邀請的手。"}
,[21807]={["key"]=21807,["storyType"]=20,["name"]="筑梦热土7",["beginId"]=2180701,["id"]=21807,["type"]=1,["section_name"]="嬉鬧的大湖（上）",["desc"]="湖邊的度假區建設，完畢~在盛夏的湖濱氣氛影響下，縱情玩樂一回吧！"}
,[20800]={["key"]=20800,["storyType"]=10,["name"]="觅己归途活动剧情1",["beginId"]=2080001,["id"]=20800,["type"]=1,["section_name"]="勞逸結合",["desc"]="刺蝽由於長期高強度工作，被納格陵強制休假。刺蝽在基地閑逛時，偶遇被丟出醫務室的總隊長。"}
,[10416]={["key"]=10416,["storyType"]=1,["name"]="第四章-第15节",["beginId"]=1041601,["id"]=10416,["type"]=1,["section_name"]="沉積敵意（上）",["desc"]="進入居民區後，總隊長目睹了住民們對鳴刃的不滿，鳴刃頗為消沈。此時護衛隊隊長雪華出現，對鳴刃和總隊長出言不遜。"}
,[10424]={["key"]=10424,["storyType"]=1,["name"]="第四章-第22节",["beginId"]=1042401,["id"]=10424,["type"]=1,["section_name"]="特殊任務（上）",["desc"]="歲稔與趕到的熔鑠交談，歲稔表示自己畏懼「研者」，所以想尋找到對付「研者」的方法，熔鑠對她的行為不予置評。鳴刃在經歷一連串事態變化後頗為迷惘，總隊長開導鳴刃。"}
,[10432]={["key"]=10432,["storyType"]=1,["name"]="第四章-第29节",["beginId"]=1043201,["id"]=10432,["type"]=1,["section_name"]="雙重困境",["desc"]="收束塔中的歲稔一直感覺不安，但仍堅持繼續自己的實驗。而面對越來越多的異變造物，第五分隊逐漸吃力，旋律要求把自己放下，表示自己也有作戰能力，不希望被當成玩偶娃娃。總隊長與鳴刃前往收束塔的路上發現造物已經異變，情況越發艱難。"}
,[10440]={["key"]=10440,["storyType"]=1,["name"]="第四章-第36节",["beginId"]=1044001,["id"]=10440,["type"]=1,["section_name"]="神經織網（上）",["desc"]="進入了收束塔的眾人發現自己被困在了奇怪的黑暗之中。總隊長在漆黑的意識告知下，尋找到了正確的方向。到達收束塔頂層後，歲稔為了延長實驗體充能的時間，選擇自體產生異變，阻攔眾人。"}
,[10448]={["key"]=10448,["storyType"]=1,["name"]="第四章-第44节",["beginId"]=1044801,["id"]=10448,["type"]=1,["section_name"]="白鳥掠影",["desc"]="歲稔與熔鑠交談，歲稔表示自己不明白鳴刃為何如此袒護那些異邦人，熔鑠則表示笨蛋的想法與其他人不同。交談過後，熔鑠看到總隊長及第五分隊的人正在走來，但此時第二代統治者製造的神秘造物出現，將總隊長等人帶入了統治者朝暉和夜暝所在的視界中。"}
,[21919]={["key"]=21919,["storyType"]=21,["name"]="异态侵蚀13",["beginId"]=2191901,["id"]=21919,["type"]=1,["section_name"]="復仇（上）",["desc"]="眾人與希羅對峙，得知希羅的目的是把異態體當作超遠端武器投射到外星。由於無法談攏，總隊長只能用武力阻止希羅。"}
,[20912]={["key"]=20912,["storyType"]=11,["name"]="云端行迹活动剧情13",["beginId"]=2091201,["id"]=20912,["type"]=1,["section_name"]="無聲蘇醒（上）",["desc"]="跟隨白鳥來到實驗室，涅毒正在這裡處理視界的程式。閃電詢問白鳥關於視界的問題，白鳥回答了相關的問題，並告知朝暉和夜暝無法找到出口是因為潛意識中不願意離開這裡。朝暉拒絕承認此事。"}
,[10504]={["key"]=10504,["storyType"]=1,["name"]="第五章-第3节",["beginId"]=1050401,["id"]=10504,["type"]=1,["section_name"]="暮色如鏽（下）",["desc"]="黑石軍事基地發生異常情況，兩名帶隊的NSS人員疑似與突然出現的造物有所關聯。"}
,[21008]={["key"]=21008,["storyType"]=12,["name"]="朝花夕誓活动剧情9",["beginId"]=2100801,["id"]=21008,["type"]=1,["section_name"]="不自知的",["desc"]="銀羽意外陷入神秘洞窟，根據環境猜測這裡就是蟲巢，差點被出現的失控造物首領-巨蠍偷襲。卡梅爾其他人擔心銀羽會遭遇危險，灼碧展開自己的全新武裝，利用彈射趕赴銀羽身邊。而銀羽也決定正視自己的速度優勢，引走巨蠍。"}
,[10520]={["key"]=10520,["storyType"]=1,["name"]="第五章-第16节",["beginId"]=1052001,["id"]=10520,["type"]=1,["section_name"]="暗夜疾行",["desc"]="阿萊西婭與好友薇娜談到機械天使所攜帶的“界楔”的事情，談完後阿萊西婭想起有急事後離開，留下薇娜自言自語，感歎地球人的友誼。"}
,[10528]={["key"]=10528,["storyType"]=1,["name"]="第五章-第24节",["beginId"]=1052801,["id"]=10528,["type"]=1,["section_name"]="細微差別",["desc"]="中央政司的參會者看到稽查者使用造物核心為自己補充能量的影像後，霍華德對這次出現的稽查者做了更詳細的分析。"}
,[10536]={["key"]=10536,["storyType"]=1,["name"]="第五章-第32节",["beginId"]=1053601,["id"]=10536,["type"]=1,["section_name"]="淵默靜待（下）",["desc"]="化身成薇娜的神秘人向地下基地裏的其他人發起襲擊，並稱這是為了促使接受了生體改造的阿萊西婭完全發揮出改造後的效果。"}
,[10544]={["key"]=10544,["storyType"]=1,["name"]="第五章-第40节",["beginId"]=1054401,["id"]=10544,["type"]=1,["section_name"]="最終一擊（下）",["desc"]="昆侖使用蓄能完成的新式武裝，將巨型稽查者的外部裝甲擊穿，並將它徹底毀滅成了殘渣。"}
,[21120]={["key"]=21120,["storyType"]=13,["name"]="虚海奇谭活动剧情11",["beginId"]=2112001,["id"]=21120,["type"]=1,["section_name"]="逐愛之人（上）",["desc"]="劫掠天王表示只要總隊長與其約會，就會放棄女王的賜福。總隊長經過考慮後答應了。在約會結束後，劫掠天王向總隊長表明自己的心意，並兌現了承諾。總隊長通過觸摸日記殘頁，再次看到了阿詩蒂的記憶。"}
,[20113]={["key"]=20113,["storyType"]=2,["name"]="卡提那个人活动第14节",["beginId"]=2011301,["id"]=20113,["type"]=1,["section_name"]="破釜沉舟",["desc"]="帶著不完整的陷阱，卡提那向異變者發起挑戰。"}
,[21200]={["key"]=21200,["storyType"]=14,["name"]="白垩行旅活动剧情1",["beginId"]=2120001,["id"]=21200,["type"]=1,["section_name"]="烽煙逆旅",["desc"]="三年前，瑞威地區。龍弦和旋律準備北上執行機密任務，卻被邊防士兵阻攔，無奈只能另尋途徑。根據你的指示，她們來到一處邊境小鎮，遇見了同樣滯留此地的廚師魁紂。面對眼下的困境，你提出了一個辦法……"}
,[10616]={["key"]=10616,["storyType"]=1,["name"]="第六章-第9节",["beginId"]=1061601,["id"]=10616,["type"]=1,["section_name"]="苔原燭光（下）",["desc"]="總隊長在戰鬥後與利茲接觸，發現利茲的態度有所軟化。另一方，希恩逐漸適應與難民們的生活，阿萊西婭得知後與美狄亞嘲諷希恩。"}
,[10624]={["key"]=10624,["storyType"]=1,["name"]="第六章-第16节",["beginId"]=1062401,["id"]=10624,["type"]=1,["section_name"]="未定猜想（下）",["desc"]="清理完物資被劫地點附近的造物後，洛貝拉顯露疲憊神色，總隊長勸洛貝拉注意休息，洛貝拉表示總隊長在勸誡別人前，先想想自己是否做到吧。"}
,[10632]={["key"]=10632,["storyType"]=1,["name"]="第六章-第24节",["beginId"]=1063201,["id"]=10632,["type"]=1,["section_name"]="第一節點（下）",["desc"]="擊敗藏在高濃度NOVA液體裏的造物後，總隊長決定炸毀此處的主控終端，切斷能量供應。在裝設好的炸藥爆炸後，眾人趕赴佩謝拉密巢。"}
,[10648]={["key"]=10648,["storyType"]=1,["name"]="第六章-第34节",["beginId"]=1064801,["id"]=10648,["type"]=1,["section_name"]="高維侵蝕（上）",["desc"]="“重塑計畫”開啟，眾人逃到海邊，薩斯塔感受到超乎尋常的NOVA能量反應，繼而海面出現奇異花紋，巨大的金色機械造物從海中出現。"}
,[21312]={["key"]=21312,["storyType"]=15,["name"]="魔导少女活动剧情10",["beginId"]=2131201,["id"]=21312,["type"]=1,["section_name"]="魔法真諦（上）",["desc"]="伊根在戰鬥中依靠自身重新獲得了光明NOVA能量的使用能力，再次向薇薇發起挑戰。"}
,[20305]={["key"]=20305,["storyType"]=5,["name"]="袅韵个人活动6",["beginId"]=2030501,["id"]=20305,["type"]=1,["section_name"]="分子料理（上）",["desc"]="總隊長與裊韻誤入了霖的分子料理實驗室。"}
,[21408]={["key"]=21408,["storyType"]=16,["name"]="冬日速递6",["beginId"]=2140801,["id"]=21408,["type"]=1,["section_name"]="逃亡者（上）",["desc"]="眾人來到諾斯板塊後，在森林中偶遇了托爾。托爾瞭解你們的目的後，帶著你們前往遭受過神秘造物襲擊的倉庫區域。"}
,[10720]={["key"]=10720,["storyType"]=1,["name"]="第七章-第11节",["beginId"]=1072001,["id"]=10720,["type"]=1,["section_name"]="侵蝕天災（上）",["desc"]="卡維婭在夢境中重溫了過去的記憶，爾後從夢中驚醒，醒來後發現底層出現侵蝕天災預兆。卡維婭擔心再次出現大規模的侵蝕天災，決定去找奧丁的使者，看能否與奧丁取得聯繫。"}
,[10728]={["key"]=10728,["storyType"]=1,["name"]="第七章-第18节",["beginId"]=1072801,["id"]=10728,["type"]=1,["section_name"]="懸空天廊",["desc"]="踏上懸空天廊後，天空雲層出現聚集跡象，弗麗嘉判斷出這是侵蝕天災大規模擴散時的徵兆，催促總隊長與烏魯魯加快速度離開天廊，避免遭受天災黑霧侵染。"}
,[21504]={["key"]=21504,["storyType"]=17,["name"]="裂空活动5",["beginId"]=2150401,["id"]=21504,["type"]=1,["section_name"]="心淵裂隙（上）",["desc"]="即便內心委屈，裂空逐漸對身邊的事物產生懷疑——夥伴的行為看起來有些反常。"}
,[20513]={["key"]=20513,["storyType"]=7,["name"]="夏日海韵活动剧情12",["beginId"]=2051301,["id"]=20513,["type"]=1,["section_name"]="海洋之心（上）",["desc"]="海灘之上驟然變天，NOVA能量所化的海洋生物發生躁動，對在場隊員發起攻擊。"}
,[21600]={["key"]=21600,["storyType"]=18,["name"]="意欲地牢1",["beginId"]=2160001,["id"]=21600,["type"]=1,["section_name"]="異態體",["desc"]="你不知道為什麼冕羽一直躲著你，你主動詢問她卻只得到一個模棱兩可的答案。後來烏琳出現，冕羽、克拉倫特以及你，接下與異態體有關的任務，三人一同返回了地球。然而在調查別墅時遭遇陷阱，你們向別墅地下掉去。"}
,[20609]={["key"]=20609,["storyType"]=8,["name"]="幻梦逸旅活动剧情10",["beginId"]=2060901,["id"]=20609,["type"]=1,["section_name"]="標記與所有物",["desc"]="調查任務完結後，G.G.G.和NCP人員交談，指出工廠一直隱藏的秘密應該就是巨型造物。另一邊總隊長帶領C.C.C.前往醫療室進行檢查，C.C.C.和總隊長交談後突然提出自己對總隊長越來越有興趣了，要給總隊長做下“標記”。"}
,[21712]={["key"]=21712,["storyType"]=19,["name"]="假日共游12",["beginId"]=2171201,["id"]=21712,["type"]=1,["section_name"]="悠長幻夢（下）",["desc"]="擊敗巨型造物後，歲稔詢問它為什麼會因為智慧而感到痛苦，在聽巨型造物訴說後，歲稔逐漸明白了其中的原因。而你在巨型造物口中得知改造者的資訊後，承諾將它送去NCP的新研究所，給予它一個可以與人交流的正常環境。"}
,[20705]={["key"]=20705,["storyType"]=9,["name"]="奇迹之夜活动剧情6",["beginId"]=2070501,["id"]=20705,["type"]=1,["section_name"]="人間喜劇",["desc"]="“斷片集”正是曾經收留培養星椋和西爾維婭的馬戲團，在機械天使的戰火中被摧毀，現正在進行重建巡演，星椋沉浸在重逢喜悅中，緹爾鋒卻暗示你進一步說話。"}
,[21808]={["key"]=21808,["storyType"]=20,["name"]="筑梦热土8",["beginId"]=2180801,["id"]=21808,["type"]=1,["section_name"]="嬉鬧的大湖（下）",["desc"]="刃齒與阿瑞斯的機車追逐以雙雙墜入湖中告終……"}
,[21824]={["type"]=1,["id"]=21824,["desc"]="大家在倉庫中存放了什麼珍視的物品呢？偷偷看一眼吧~",["line"]=20000,["name"]="筑梦热土24",["key"]=21824,["storyType"]=20,["section_name"]="建造貯存倉庫",["beginId"]=2182401}
,[20817]={["key"]=20817,["storyType"]=10,["name"]="觅己归途活动剧情11",["beginId"]=2081701,["id"]=20817,["type"]=1,["section_name"]="自我演繹（下）",["desc"]="幫派聯盟的人早就知道卡洲貴族有問題並留了一手。在她們敗北後，多拉把能夠證明兩者交易的證據檔交給了刺蝽和總隊長。"}
,[21920]={["key"]=21920,["storyType"]=21,["name"]="异态侵蚀14",["beginId"]=2192001,["id"]=21920,["type"]=1,["section_name"]="復仇（下）",["desc"]="眾人成功阻止希羅並且拿到限制器，然而突然有人開槍偷襲總隊長——那人正是維拉。"}
