,[20514]={["key"]=20514,["storyType"]=7,["name"]="夏日海韵活动剧情13",["beginId"]=2051401,["id"]=20514,["type"]=1,["section_name"]="海洋之心（下）",["desc"]="總隊長與赤溟與海洋意志進行了精神鏈接，隨後回到了海灘戰場，擋下了克拉肯的攻勢。"}
,[10305]={["key"]=10305,["storyType"]=1,["name"]="第三章-第3节",["beginId"]=1030501,["id"]=10305,["type"]=1,["section_name"]="無過往之人（下）",["desc"]="在這個房間裏，總隊長與普羅米修斯不僅遇到了造物，還遇到了從容納艙裏出現的，毫無過往記憶的神秘少女。"}
,[10313]={["key"]=10313,["storyType"]=1,["name"]="第三章-第9节",["beginId"]=1031301,["id"]=10313,["type"]=1,["section_name"]="尖牙利齒（上）",["desc"]="不遠處傳來熟悉的聲音，刃齒和一群碎星人起了沖突。面對糾纏刃齒，要求她擔任部落首領的碎星人，只能選擇用武力交流了。"}
,[10321]={["key"]=10321,["storyType"]=1,["name"]="第三章-第16节",["beginId"]=1032101,["id"]=10321,["type"]=1,["section_name"]="附生暗影（上）",["desc"]="總隊長等人經過某個冷凍艙群時聽到求助聲，瑪哈特放出求助者後，求助者自稱叫做努特，並對總隊長等異邦人非常感興趣，要求和總隊長打上一架。"}
,[10329]={["key"]=10329,["storyType"]=1,["name"]="第三章-第24节",["beginId"]=1032901,["id"]=10329,["type"]=1,["section_name"]="往昔幻影（上）",["desc"]="有了自我認知的瑪哈特堅持反抗奧西裏斯，不願意被抹去自我思想，奧西裏斯想看瑪哈特為了自由能反抗到什麽程度。"}
,[10337]={["key"]=10337,["storyType"]=1,["name"]="第三章-第31节",["beginId"]=1033701,["id"]=10337,["type"]=1,["section_name"]="疾速奔行（上）",["desc"]="總隊長帶領眾人登上軌道電梯後，發現穆特和造物追趕而來。刃齒斥責穆特，穆特說自己只是接受了別人的命令，不能反抗。總隊長勸說穆特，但穆特表示只能這樣做了。"}
,[10345]={["key"]=10345,["storyType"]=1,["name"]="第三章-第39节",["beginId"]=1034501,["id"]=10345,["type"]=1,["section_name"]="手握命運",["desc"]="面對開始互相融合的造物，瑪哈特表示自己是合成人，也算是造物的一種，不會被其他造物視為敵人，自己可以留下來對付這些融合造物，讓總隊長和第三分隊隊員們趕緊離開這裏。"}
,[21713]={["key"]=21713,["storyType"]=19,["name"]="假日共游13",["beginId"]=2171301,["id"]=21713,["type"]=1,["section_name"]="落幕餘聲",["desc"]="一切落下帷幕，歲稔與你漫步於花園之中，交談了關於變化和改變的看法。歲稔決定體驗更多的地球生活以汲取靈感，邀請你作為嚮導。你預感到，一段溫柔細膩的時光會就此開啟。"}
,[20706]={["key"]=20706,["storyType"]=9,["name"]="奇迹之夜活动剧情7",["beginId"]=2070601,["id"]=20706,["type"]=1,["section_name"]="陰翳禮贊",["desc"]="緹爾鋒表明身份，她和西爾維婭均是第十三調查局成員，借調到NERI部隊協助總隊長調查， 馬戲團可能是異變事件的罪魁禍首，拉確認尼克羅的叛徒就隱藏在這裏。"}
,[10401]={["key"]=10401,["storyType"]=1,["name"]="第四章-第1节",["beginId"]=1040101,["id"]=10401,["type"]=1,["section_name"]="不諧之音",["desc"]="地球總部的中央政司通過決定，要求總隊長返回地球述職。摩爾市長與滄副司令交流後，決定靜觀情況，等待幕後黑手出現。前哨基地中，卡蒂雅因為總部傳來的命令而憤怒不已，總隊長安撫卡蒂雅時傳來第四及第五分隊的消息，經過商討後，總隊長決定獨自前往第五分隊所在板塊。"}
,[10409]={["key"]=10409,["storyType"]=1,["name"]="第四章-第8节",["beginId"]=1040901,["id"]=10409,["type"]=1,["section_name"]="草原異跡（上）",["desc"]="總隊長和鳴刃經過青霞原野時，鳴刃感嘆風景美麗，總隊長表示地球也有很美的風景，鳴刃表示自己也想看地球的風景，總隊長說如果鳴刃前往地球，自己會招待她。"}
,[10417]={["key"]=10417,["storyType"]=1,["name"]="第四章-第16节",["beginId"]=1041701,["id"]=10417,["type"]=1,["section_name"]="沉積敵意（下）",["desc"]="與雪華動手後，雪華向其他人宣告鳴刃帶領異邦人再次進入天階原，遭到鳴刃嚴肅訓斥，鳴刃以自己的統治者權柄擔保不會做出危害天階原的事情，並要求雪華帶自己和總隊長前往護衛隊駐地。"}
,[10433]={["key"]=10433,["storyType"]=1,["name"]="第四章-第30节",["beginId"]=1043301,["id"]=10433,["type"]=1,["section_name"]="孤注一擲（上）",["desc"]="第五分隊陷入苦戰，旋律要求自己單人執行任務，並列出了自己的優勢。眾人尊重她的想法，將關閉閥門的任務交給旋律，其他人則吸引大部分造物離開任務目的地附近。總隊長與女王蜂交談後想尋求前哨基地支援，但總部派來的特遣人員拒絕了支援請求。"}
,[10441]={["key"]=10441,["storyType"]=1,["name"]="第四章-第37节",["beginId"]=1044101,["id"]=10441,["type"]=1,["section_name"]="神經織網（下）",["desc"]="異變後的歲稔被眾人擊敗，鳴刃斥責歲稔背棄了那些擁護她的人。但歲稔沈默後仍決定以自己的核心替實驗體供能，喚醒最終實驗體。"}
,[21921]={["key"]=21921,["storyType"]=21,["name"]="异态侵蚀15",["beginId"]=2192101,["id"]=21921,["type"]=1,["section_name"]="黑幕（上）",["desc"]="維拉主動釋放異態體，是為了收集足夠多的資料方便賣錢。當她得知妮娜能夠與異態體交流後，決定將異態體和妮娜一起帶走。維拉主動殿後，為的是伺機偷襲總隊長。然而她的陰謀和異常早被看穿，總隊長找機會偷襲維拉，皮洛可成功搶回了限制器，維拉只能使出最後的殺手鐧。"}
,[20914]={["key"]=20914,["storyType"]=11,["name"]="云端行迹活动剧情15",["beginId"]=2091401,["id"]=20914,["type"]=1,["section_name"]="追溯本源（上）",["desc"]="眾人前往尋找寄放視界自我意識的造物。在路上朝暉感歎工具誕生自我意識太過奇妙，女王蜂表示這是因應科技發展而很合適的事情，並說以後要是真有了自我意識的AI，自己會想嘗試和它們組成虛擬偶像團體。"}
,[22001]={["key"]=22001,["storyType"]=22,["name"]="星间纪行-阿卡斯",["beginId"]=2200001,["id"]=22001,["type"]=1,["section_name"]="被放逐的失群者",["desc"]="作為被放逐的一員的阿卡斯與機械小車卡西妮婭來到地球，為“重塑”計畫做準備。阿卡斯在地球經歷了漫長的時間後，體會到離別的重量，卻也堅定了完成使命的決心。"}
,[10505]={["key"]=10505,["storyType"]=1,["name"]="第五章-第4节",["beginId"]=1050501,["id"]=10505,["type"]=1,["section_name"]="帷幕初啟（上）",["desc"]="在趕往指揮中心的途中遇到自稱“伊芙琳”的工作人員，滄果斷對其開槍，伊芙琳坦白身份是“索菲亞之瞳”的成員，目的就是為了拖住滄及總隊長等人。"}
,[10513]={["key"]=10513,["storyType"]=1,["name"]="第五章-第9节",["beginId"]=1051301,["id"]=10513,["type"]=1,["section_name"]="長夜不寧（下）",["desc"]="總隊長接近稽查者，嘗試與暫時附在稽查者身上的系爾溝通，但失敗了。重新獲得意識的稽查者十分渴望特化核心所散發的能量，對總隊長緊追不放。"}
,[10521]={["key"]=10521,["storyType"]=1,["name"]="第五章-第17节",["beginId"]=1052101,["id"]=10521,["type"]=2,["section_name"]="none",["desc"]="none"}
,[10529]={["key"]=10529,["storyType"]=1,["name"]="第五章-第25节",["beginId"]=1052901,["id"]=10529,["type"]=1,["section_name"]="相比之下（上）",["desc"]="艾格遇到卡洲康拉德家族的貴族格特魯德，格特魯德勸說艾格與自己合作，在霍華德卸任後爭取擔任總司令的職位。艾格表示很感興趣，讓格特魯德詳細說明。"}
,[10537]={["key"]=10537,["storyType"]=1,["name"]="第五章-第33节",["beginId"]=1053701,["id"]=10537,["type"]=1,["section_name"]="遁入盲區（上）",["desc"]="阿萊西婭返回地下基地後發現其他人消失不見，詫異之下到處查找。恰好此時總隊長也通過另一條通道進入地下基地，也同樣為看不到其他人而迷惑。"}
,[10545]={["key"]=10545,["storyType"]=1,["name"]="第五章-第41节",["beginId"]=1054501,["id"]=10545,["type"]=1,["section_name"]="往昔星辰",["desc"]="危機干預小組來到議會廳，伊德海拉麵對總隊長發難，被艾格用探索隊的成員完美駁回了伊德海拉的指控。之後，總隊長反過來指控阿卡斯。"}
,[10601]={["key"]=10601,["storyType"]=1,["name"]="第六章-第1节",["beginId"]=1060101,["id"]=10601,["type"]=1,["section_name"]="蒼白之記",["desc"]="艾格請求總隊長前往援助處於困境的北境戰區，總隊長答允後，艾格調配洛貝拉及旋流陪同總隊長前往北境戰區。總隊長離開辦公室後遇到滄，兩人談起下落不明的阿卡斯。"}
,[10609]={["key"]=10609,["storyType"]=1,["name"]="第六章-第5节",["beginId"]=1060901,["id"]=10609,["type"]=1,["section_name"]="高塔之上（下）",["desc"]="奧諾拉上校告知總隊長北境戰區的情況後，洛貝拉告知眾人已經搭建了與外界的暫時通訊頻道，艾格在全息視頻通話中宣佈任命總隊長為北境戰區的臨時最高總指揮。"}
,[10617]={["key"]=10617,["storyType"]=1,["name"]="第六章-第10节",["beginId"]=1061701,["id"]=10617,["type"]=1,["section_name"]="歲月漫長",["desc"]="龍弦與艾格交談，兩人對阿卡斯的初始檔案感到震驚，沒想到阿卡斯竟然在這麼早之前就來到了地球。總隊長在與漆黑意念交談時，意外得知研者的“重塑計畫”。"}
,[10625]={["key"]=10625,["storyType"]=1,["name"]="第六章-第17节",["beginId"]=1062501,["id"]=10625,["type"]=1,["section_name"]="未來景象",["desc"]="總隊長與洛貝拉來到海邊，觀察後發現海水受NOVA能量影響已經變成了無法接觸的狀態，想要進入海中窺探能量聚合點的狀態，就必須借用“源島國際”的特製防護服和特定設施。"}
,[10633]={["key"]=10633,["storyType"]=1,["name"]="第六章-第25节",["beginId"]=1063301,["id"]=10633,["type"]=1,["section_name"]="落雪無聲",["desc"]="眾人進入佩謝拉密巢後，在趕路過程中總隊長發現利茲狀態不對，詢問後利茲搪塞回答。彌鈴找到在難民聚居點的希恩，告知阿卡斯有任務交代給她。"}
,[10641]={["key"]=10641,["storyType"]=1,["name"]="第六章-第30节",["beginId"]=1064101,["id"]=10641,["type"]=1,["section_name"]="過往難追（下）",["desc"]="從昏迷中醒來的總隊長得知自己的意識有被入侵過的痕跡，但無法得知到底是什麼時候發生的事情。思索後總隊長決定先擱置此事，前往外部作戰區對付來襲的造物。"}
,[10649]={["key"]=10649,["storyType"]=1,["name"]="第六章-第35节",["beginId"]=1064901,["id"]=10649,["type"]=1,["section_name"]="高維侵蝕（下）",["desc"]="總隊長與洛貝拉各自驅使機神趨同作戰，順利擊敗出現的神秘金色機械造物，以及其他高等級造物。但由於“重塑計畫”已開啟，總隊長讓洛貝拉想辦法暫時中止了同化，考慮後續如何應對。"}
,[21314]={["key"]=21314,["storyType"]=15,["name"]="魔导少女活动剧情12",["beginId"]=2131401,["id"]=21314,["type"]=1,["section_name"]="其名為愛（上）",["desc"]="面對強大的大灰，已經筋疲力盡的眾人陷入劣勢。好在刺蝽對這種情況早有準備，讓總隊長使用魔導晶管做成的魔導子彈，使大灰體內的能量不斷洩露。"}
,[20307]={["key"]=20307,["storyType"]=5,["name"]="袅韵个人活动8",["beginId"]=2030701,["id"]=20307,["type"]=1,["section_name"]="假說推演",["desc"]="眾人最終在花房匯合，共同面對那只覺醒了智能的造物。"}
,[10705]={["key"]=10705,["storyType"]=1,["name"]="第七章-第2节",["beginId"]=1070501,["id"]=10705,["type"]=1,["section_name"]="陌生地域（上）",["desc"]="總隊長進入諾斯板塊後遇到弗麗嘉，從弗麗嘉口中得知自己身處奧丁所統治的諾斯板塊，奧丁還依託世界樹建立了名為“尤克希爾”的國度。"}
,[10713]={["key"]=10713,["storyType"]=1,["name"]="第七章-第7节",["beginId"]=1071301,["id"]=10713,["type"]=1,["section_name"]="底層國度（下）",["desc"]="休整過後，總隊長與烏魯魯、弗麗嘉動身前往其他國度。希恩進入諾斯板塊後跌落神秘區域，被隔離監控，三十個系統時後進行數據清除。"}
,[10721]={["key"]=10721,["storyType"]=1,["name"]="第七章-第12节",["beginId"]=1072101,["id"]=10721,["type"]=1,["section_name"]="侵蝕天災（下）",["desc"]="卡維婭與奧丁的使者-格恩達爾都無法與奧丁取得聯繫，而身處世界樹頂端的奧丁正在疑惑於侵蝕天災為何仍在增強。"}
,[10729]={["key"]=10729,["storyType"]=1,["name"]="第七章-第19节",["beginId"]=1072901,["id"]=10729,["type"]=1,["section_name"]="聖諭殿堂（上）",["desc"]="雲層的範圍還在擴大，弗麗嘉表示這次的擴張速度比自己之前見過的任何一次都快，必須儘快進入米德加爾特範圍，三人以最快速度前進。"}
,[21506]={["key"]=21506,["storyType"]=17,["name"]="裂空活动7",["beginId"]=2150601,["id"]=21506,["type"]=1,["section_name"]="幻象",["desc"]="壓倒一個人的並非病痛，而是病床前一張張冷漠的面龐……裂空該如何抉擇，所謂的幻覺究竟源自內心，還是所見所經歷的一切？"}
,[20515]={["key"]=20515,["storyType"]=7,["name"]="夏日海韵活动剧情14",["beginId"]=2051501,["id"]=20515,["type"]=1,["section_name"]="第十二夜（上）",["desc"]="受赤溟的鼓勵感染，海洋意志化作她的外形，第一次真正出現在人類面前，為了守護心愛的“孩子”們，擊敗了克拉肯。"}
