,[10010]={["key"]=10010,["storyType"]=1,["name"]="序章-第8节",["beginId"]=1000756,["id"]=10010,["type"]=1,["section_name"]="工廠",["desc"]="造物工廠已被摧毀，然而感染並沒有停止。"}
