,[10250]={["key"]=10250,["storyType"]=1,["name"]="第二章-第29节",["beginId"]=1025001,["id"]=10250,["type"]=1,["section_name"]="失敗超新星",["desc"]="絕境逢生的尼德霍格小分隊在拌嘴中又遇上了新的阻擋，目的地仍在前方。"}
,[20500]={["key"]=20500,["storyType"]=7,["name"]="夏日海韵活动剧情1",["beginId"]=2050001,["id"]=20500,["type"]=1,["section_name"]="仲夏夜之夢",["desc"]="總隊長從一場關於深海的夢中驚醒，發現因為恒溫裝置損壞，前哨基地陷入了夏日高溫大危機。"}
,[20516]={["key"]=20516,["storyType"]=7,["name"]="夏日海韵活动剧情15",["beginId"]=2051601,["id"]=20516,["type"]=1,["section_name"]="第十二夜（下）",["desc"]="成功化解了風波後，眾人舉辦起了歡快的海濱慶典，回到基地的赤溟與總隊長依依惜別。"}
