,[10306]={["key"]=10306,["storyType"]=1,["name"]="第三章-第4节",["beginId"]=1030601,["id"]=10306,["type"]=1,["section_name"]="重重守衛（上）",["desc"]="普羅米修斯認出少女是碎星禁忌的合成人，在普羅米修斯的追問下，自稱瑪哈特的少女回想起一些零碎的記憶。"}
,[10314]={["key"]=10314,["storyType"]=1,["name"]="第三章-第10节",["beginId"]=1031401,["id"]=10314,["type"]=1,["section_name"]="尖牙利齒（下）",["desc"]="面對這些幾乎無法交流的戰爭屬民，瑪哈特駁斥了她們，並說阿圖姆的想法與戰爭屬民的想法完全不同。"}
,[10322]={["key"]=10322,["storyType"]=1,["name"]="第三章-第17节",["beginId"]=1032201,["id"]=10322,["type"]=1,["section_name"]="附生暗影（下）",["desc"]="打完架後的努特突然暈倒，總隊長等人將她放回冷凍艙後離開。再次醒來的努特被伊西斯控製了軀體，伊西斯打算實施破壞計劃，被來到的卡尼斯等人聽到。"}
,[10330]={["key"]=10330,["storyType"]=1,["name"]="第三章-第25节",["beginId"]=1033001,["id"]=10330,["type"]=1,["section_name"]="往昔幻影（下）",["desc"]="打敗奧西裏斯後，瑪哈特說自己實際並不討厭阿圖姆，甚至很感謝她。但自己在核心裏沒有感受到阿圖姆對生的執著，她是自願接受毀滅的，奧西裏斯嘗試復活根本沒有意義。"}
,[10338]={["key"]=10338,["storyType"]=1,["name"]="第三章-第32节",["beginId"]=1033801,["id"]=10338,["type"]=1,["section_name"]="疾速奔行（下）",["desc"]="穆特被擊敗後，出示自己手上的控製器，打算引爆造物的自爆裝置，和眾人同歸於盡。刃齒想把控製器搶過來，但穆特快速按下了引爆。"}
,[10346]={["key"]=10346,["storyType"]=1,["name"]="第三章-第40节",["beginId"]=1034601,["id"]=10346,["type"]=1,["section_name"]="侵吞戰影（上）",["desc"]="奈芙蒂斯攔在了眾人跟前，表示自己與別人達成了協議，會用盡一切力量來攔阻總隊長等人前往面見阿努比斯。奈芙蒂斯召喚了機神協同作戰，面對這個情況，總隊長也召喚了漆黑。"}
,[20708]={["key"]=20708,["storyType"]=9,["name"]="奇迹之夜活动剧情8",["beginId"]=2070801,["id"]=20708,["type"]=1,["section_name"]="六尺之下（上）",["desc"]="排練之餘，尼克羅的叛徒凱貝潔特藏在了西爾維婭的意識裏，此刻突然現身發難。"}
,[21811]={["key"]=21811,["storyType"]=20,["name"]="筑梦热土11",["beginId"]=2181101,["id"]=21811,["type"]=1,["section_name"]="新的目標（上）",["desc"]="觀光活動即將進入二階段，與卡提那一同迎接即將到來的考驗。"}
,[10410]={["key"]=10410,["storyType"]=1,["name"]="第四章-第9节",["beginId"]=1041001,["id"]=10410,["type"]=1,["section_name"]="草原異跡（下）",["desc"]="清理完感染造物，鳴刃在清理造物軀殼時發現有類似直接感染體的情況，感覺疑惑但並未深究。但在此時，有更多的感染造物出現了。"}
,[10418]={["key"]=10418,["storyType"]=1,["name"]="第四章-第17节",["beginId"]=1041801,["id"]=10418,["type"]=1,["section_name"]="失控造物（上）",["desc"]="在雪華的幫助下搜尋了居民區，但仍無法找到第五分隊的蹤跡。總隊長和鳴刃正準備離開居民區時，護衛隊的造物守衛突然失控。"}
,[10426]={["key"]=10426,["storyType"]=1,["name"]="第四章-第23节",["beginId"]=1042601,["id"]=10426,["type"]=1,["section_name"]="特殊任務（下）",["desc"]="在戰鬥後赤夕短暫回復理性，與總隊長和鳴刃交談。赤夕告知總隊長，那位來到天階原的「研者」說出了關於地球的消息，並要求以這為交易，換取地球的科技。"}
,[10442]={["key"]=10442,["storyType"]=1,["name"]="第四章-第38节",["beginId"]=1044201,["id"]=10442,["type"]=1,["section_name"]="災禍核心（上）",["desc"]="最終實驗體-毒禍魘使蘇醒後，揭示了自己的真正身份是「研者」瑪勒絲。在軀殼被毀滅後，瑪勒絲意識轉移到了「災禍之獸」的核心之中。瑪勒絲以自己連接的蜂群意識網絡，威脅鳴刃與總隊長對戰，奪走總隊長的NOVA核心。"}
,[21907]={["key"]=21907,["storyType"]=21,["name"]="异态侵蚀3",["beginId"]=2190701,["id"]=21907,["type"]=1,["section_name"]="研究所（下）",["desc"]="皮洛可等人被安保人員控制起來，好在有總隊長及時出現解圍。皮洛可想到妮娜可能還沒有逃出研究所，於是請求和總隊長同行。在總隊長同意之前，神秘人啟動陷阱，令兩人向研究所地下墜落。"}
,[20900]={["key"]=20900,["storyType"]=11,["name"]="云端行迹活动剧情1",["beginId"]=2090001,["id"]=20900,["type"]=1,["section_name"]="困境囚徒",["desc"]="總隊長和第五分隊被無名白鳥帶入困著朝暉夜暝的“視界”。總隊長醒來後十分擔心失散的第五分隊，朝暉安慰總隊長並告知視界沒有出口，不用擔心第五分隊失蹤。總隊長不相信此事，表示要想辦法離開。"}
,[20916]={["key"]=20916,["storyType"]=11,["name"]="云端行迹活动剧情17",["beginId"]=2091601,["id"]=20916,["type"]=1,["section_name"]="自由之外（上）",["desc"]="朝暉與夜暝產生爭執，朝暉難過並說自己不是一個好的統治者。夜暝安慰朝暉後詢問自己與朝暉是否已經和視界融合，無法分開了？白鳥轉過頭不做回答。夜暝告知自己與朝暉決定犧牲自己，為總隊長和第五分隊打開通路，畢竟兩人都不願意被視界禁錮吸取力量。白鰭思考後提出另一個方案。"}
,[10506]={["key"]=10506,["storyType"]=1,["name"]="第五章-第5节",["beginId"]=1050601,["id"]=10506,["type"]=1,["section_name"]="帷幕初啟（下）",["desc"]="回到地球更換新型武裝的昆侖與主導研發的維羅妮卡教授見面，維羅妮卡希望昆侖幫忙測試武裝上的情感轉換裝置。另一邊，龍弦讓納格陵和天叢雲先返回部隊駐地，等候空間門成型後出動，清除降臨的造物。"}
,[10514]={["key"]=10514,["storyType"]=1,["name"]="第五章-第10节",["beginId"]=1051401,["id"]=10514,["type"]=1,["section_name"]="天穹之上（上）",["desc"]="中央政司議會廳中霍華德宣佈組建暫時危機干預小組，並以總司令身份下達對總隊長的臨時豁免。總隊長帶著造物及稽查者在軍事基地裏穿行，漆黑疑惑總隊長為什麼心情興奮，總隊長回答這是一種自我減壓的方式。"}
,[10522]={["key"]=10522,["storyType"]=1,["name"]="第五章-第18节",["beginId"]=1052201,["id"]=10522,["type"]=1,["section_name"]="硝煙黎明",["desc"]="危機干預小組眾人一邊將稽查者引往指定地點，一邊竭力拖延稽查者的速度。另一邊，維羅妮卡耐心開導迷茫中的昆侖。"}
,[10530]={["key"]=10530,["storyType"]=1,["name"]="第五章-第26节",["beginId"]=1053001,["id"]=10530,["type"]=1,["section_name"]="相比之下（下）",["desc"]="中央政司中的眾人都因為好奇而觀看巨型稽查者及造物潮從議會大廈旁邊經過的影像，此時阿卡斯回到座位上，並對霍華德和滄露出神秘微笑。"}
,[10538]={["key"]=10538,["storyType"]=1,["name"]="第五章-第34节",["beginId"]=1053801,["id"]=10538,["type"]=1,["section_name"]="倒懸之地（上）",["desc"]="總隊長進入地下基地實驗室後，意外遇到帶有第一次探索隊遇難者記憶的造物-埃莉諾。埃莉諾得知總隊長進入基地的原委後，帶總隊長來到保密室獲取保存在這裏的資料。"}
,[20101]={["key"]=20101,["storyType"]=2,["name"]="卡提那个人活动第2节",["beginId"]=2010101,["id"]=20101,["type"]=1,["section_name"]="軍令狀",["desc"]="為了不進軍事法庭，卡提那被迫立下軍令狀與清理人奧巴瑟共同來到戈裡刻執行%s總隊長的搜尋任務。"}
,[10610]={["key"]=10610,["storyType"]=1,["name"]="第六章-第6节",["beginId"]=1061001,["id"]=10610,["type"]=1,["section_name"]="夜幕之花（上）",["desc"]="總隊長遭遇夢魘，醒來後發現隊員利茲正拿刀對著自己，從交流中得知利茲怨恨自己沒有救下在第一次探索隊中的利茲姐姐，利茲想要行兇時被總隊長反擊制住。總隊長思索後放利茲離開，利茲表情複雜。"}
,[20213]={["key"]=20213,["storyType"]=3,["name"]="蛛影活动剧情13",["beginId"]=2021301,["id"]=20213,["type"]=1,["section_name"]="模仿犯",["desc"]="輝礫本想審問一番自投羅網的蜘蛛，可“突如其來”的模仿犯問題更為嚴重，果然蛛網上的蜘蛛是困不住的。"}
,[10634]={["key"]=10634,["storyType"]=1,["name"]="第六章-第26节",["beginId"]=1063401,["id"]=10634,["type"]=1,["section_name"]="繼續深入",["desc"]="眾人在佩謝拉密巢中遭遇突變，總隊長再次醒來後發現自己回到了被利茲夜襲時的情況，質問偽裝成利茲的系爾到底想做什麼，系爾表示想與總隊長合作，對付研者。"}
,[10642]={["key"]=10642,["storyType"]=1,["name"]="第六章-第31节",["beginId"]=1064201,["id"]=10642,["type"]=1,["section_name"]="無處可逃",["desc"]="斯涅紮娜中校暗中帶隊截擊洛貝拉團隊運送的物資，在埋伏時被洛貝拉發現，洛貝拉指責斯涅紮娜等人並不知道阿卡斯的計畫到底是什麼，卻成為了阿卡斯的同夥。"}
,[10650]={["key"]=10650,["storyType"]=1,["name"]="第六章-第36节",["beginId"]=1065001,["id"]=10650,["type"]=1,["section_name"]="世界巨樹",["desc"]="返回奧爾達基地後，總隊長感覺洛貝拉狀態不對，前往休息艙尋找洛貝拉。返回帕科薩後，總隊長告知艾格，自己決定前往諾斯板塊借用世界樹系統，以儘快完善碎星的能量模型圖，尋找到核心板塊以阻止同化。"}
,[21300]={["key"]=21300,["storyType"]=15,["name"]="魔导少女活动剧情1",["beginId"]=2130001,["id"]=21300,["type"]=1,["section_name"]="閃亮登場",["desc"]="刺蝽所在的研究所被大量造物襲擊，總隊長帶著伊根和岡底斯前去救援。面對無法打敗的造物，伊根使用了刺蝽開發的魔導晶管，軀體卻因此發生爆炸。爆炸之中，伊根變成了少女的模樣。"}
,[21316]={["key"]=21316,["storyType"]=15,["name"]="魔导少女活动剧情14",["beginId"]=2131601,["id"]=21316,["type"]=1,["section_name"]="魔法永恆",["desc"]="一切事情塵埃落地，大灰在被擊敗後逃跑。伊根邀請總隊長一起觀看《魔法少女小葉》的影片，並向其表示了感謝。"}
,[20309]={["key"]=20309,["storyType"]=5,["name"]="袅韵个人活动10",["beginId"]=2030901,["id"]=20309,["type"]=1,["section_name"]="你一生的故事",["desc"]="裊韻向總隊長坦白自己的身世秘密。"}
,[10714]={["key"]=10714,["storyType"]=1,["name"]="第七章-第8节",["beginId"]=1071401,["id"]=10714,["type"]=1,["section_name"]="死亡女神",["desc"]="總隊長一行人來到死之國，見到傳說中脾氣古怪的死亡女神，卻意外發現女神竟是杜蘭德爾。杜蘭德爾以授予盧恩符文為交換，要求總隊長與自己共度一夜。"}
,[10722]={["key"]=10722,["storyType"]=1,["name"]="第七章-第13节",["beginId"]=1072201,["id"]=10722,["type"]=1,["section_name"]="裂隙之路（上）",["desc"]="進入隔離帶後，總隊長三人出現了感官超載的狀態，為了儘快離開隔離帶，總隊長背負起弗麗嘉，由烏魯魯在前面開路。弗麗嘉表示自己第一次感受到“同伴”的感覺。"}
