,[21508]={["key"]=21508,["storyType"]=17,["name"]="裂空活动9",["beginId"]=2150801,["id"]=21508,["type"]=1,["section_name"]="黃沙之下（下）",["desc"]="黃沙傾下，埋葬一段無人知曉的回憶……"}
,[20517]={["key"]=20517,["storyType"]=7,["name"]="夏日海韵活动剧情16",["beginId"]=2051701,["id"]=20517,["type"]=1,["section_name"]="神秘怪客",["desc"]="傳說中釣魚客如果久未收獲，其怨氣會凝聚成形，徘徊在水域阻撓其他釣客釣大魚，但是時代變了，你們是時候站出來，堂堂正正捍衛自己的戰利品。"}
,[21620]={["key"]=21620,["storyType"]=18,["name"]="意欲地牢12",["beginId"]=2162001,["id"]=21620,["type"]=1,["section_name"]="起點（上）",["desc"]="你們在這裡遇到了一名奇特的女性，而那個女性正是冕羽的母親——索菲亞。"}
,[21700]={["key"]=21700,["storyType"]=19,["name"]="假日共游1",["beginId"]=2170001,["id"]=21700,["type"]=1,["section_name"]="強迫假期",["desc"]="進行健康檢查後，總隊長被勒令返回地球休假，而得知這個消息的卡蒂雅請求總隊長帶上鬱鬱寡歡的歲稔。"}
,[20709]={["key"]=20709,["storyType"]=9,["name"]="奇迹之夜活动剧情9",["beginId"]=2070901,["id"]=20709,["type"]=1,["section_name"]="六尺之下（下）",["desc"]="凱貝潔特指責緹爾鋒來自劣跡斑斑的皇室獵犬家族，曾在行動中因傷害己方戰友而被軍事法庭審判。本想挑撥卻被總隊長義正言辭反駁。"}
