,[10107]={["key"]=10107,["storyType"]=1,["name"]="第一章-第6节",["beginId"]=1010701,["id"]=10107,["type"]=1,["section_name"]="轉向",["desc"]="%s一行面對突然出現的阿爾卑斯的信號改變方向，前往支援。"}
,[10115]={["key"]=10115,["storyType"]=1,["name"]="第一章-第13节",["beginId"]=1011501,["id"]=10115,["type"]=1,["section_name"]="遺言",["desc"]="失敗的阿瑞斯在履行自己的約定時被波塞冬打斷，並利用她的軀體在不破壞自身規則的前提下，告知了所有人“克羅諾斯”核心的位置。"}
