,[20310]={["key"]=20310,["storyType"]=5,["name"]="袅韵个人活动11",["beginId"]=2031001,["id"]=20310,["type"]=1,["section_name"]="新生（上）",["desc"]="總隊長帶裊韻來到了一處美麗的神秘板塊。"}
,[21413]={["key"]=21413,["storyType"]=16,["name"]="冬日速递10",["beginId"]=2141301,["id"]=21413,["type"]=1,["section_name"]="危險分子（上）",["desc"]="抵達尼克羅後，赤狼等人帶著你們來到奧西里斯的秘密實驗室。然而在閒聊的時候，奧西里斯的實驗室發生了爆炸。"}
,[10211]={["key"]=10211,["storyType"]=1,["name"]="第二章-第6节",["beginId"]=1021101,["id"]=10211,["type"]=1,["section_name"]="塔羅牌",["desc"]="第二分隊的眾人以各自的方式生存，卻看見了意料之外的俘虜，也認清了意料之外的版塊現狀，並以意外的方式解決了困境。"}
,[20422]={["key"]=20422,["storyType"]=6,["name"]="糖果活动剧情23",["beginId"]=2042201,["id"]=20422,["type"]=1,["section_name"]="故事續寫（下）",["desc"]="赭猩剛演完了故事，但渦流又感到了不滿。"}
,[10227]={["key"]=10227,["storyType"]=1,["name"]="第二章-第13节",["beginId"]=1022701,["id"]=10227,["type"]=1,["section_name"]="分歧點",["desc"]="一場戰鬥結束了，然而這僅僅是大戰的序幕。"}
,[10235]={["key"]=10235,["storyType"]=1,["name"]="第二章-第18节",["beginId"]=1023501,["id"]=10235,["type"]=1,["section_name"]="真面目",["desc"]="布倫希爾德嘗試抵抗身體發生的異變，然而被吞噬殆盡的意識最終還是讓出了身體的控制權。"}
,[10243]={["key"]=10243,["storyType"]=1,["name"]="第二章-第23节",["beginId"]=1024301,["id"]=10243,["type"]=1,["section_name"]="未來視",["desc"]="絲卡蒂向洛基述說自己看到的未來，但想要改變那個沒有希望的未來，卻要付出沉重的代價。"}
,[10251]={["key"]=10251,["storyType"]=1,["name"]="第二章-第30节",["beginId"]=1025101,["id"]=10251,["type"]=1,["section_name"]="共軛性",["desc"]="尼德霍格的製造加班加點，世界樹的“解決方案”也在繼續。"}
,[20502]={["key"]=20502,["storyType"]=7,["name"]="夏日海韵活动剧情2",["beginId"]=2050201,["id"]=20502,["type"]=1,["section_name"]="熱島效應",["desc"]="在酷熱難耐中，總隊長挺身而出救出了中暑的隊員，並決定帶領部分隊員出發探索一處疑似存在海洋的板塊。"}
,[21605]={["key"]=21605,["storyType"]=18,["name"]="意欲地牢3",["beginId"]=2160501,["id"]=21605,["type"]=1,["section_name"]="神秘地下（下）",["desc"]="你恢復意識後，發現冕羽和克拉倫特被困。你救出她們後獲得了構成異態體的其中一顆能量珠，並且得知這裡的空間會受到慾望的影響，瑞絲揭示剛剛的房間是受到冕羽的影響。"}
,[10307]={["key"]=10307,["storyType"]=1,["name"]="第三章-第5节",["beginId"]=1030701,["id"]=10307,["type"]=1,["section_name"]="重重守衛（下）",["desc"]="總隊長與普羅米修斯準備離開，瑪哈特懇求帶上自己，總隊長答應瑪哈特的請求。"}
,[10315]={["key"]=10315,["storyType"]=1,["name"]="第三章-第11节",["beginId"]=1031501,["id"]=10315,["type"]=1,["section_name"]="管理者（上）",["desc"]="趕來的荷魯斯發現瑪哈特是碎星禁忌的合成人，而且長相與阿圖姆幾乎一樣，認為總隊長等人與戰爭屬民在計劃陰謀，拒絕聽取解釋並首先動手。"}
,[10323]={["key"]=10323,["storyType"]=1,["name"]="第三章-第18节",["beginId"]=1032301,["id"]=10323,["type"]=1,["section_name"]="前行之路（上）",["desc"]="發生異變的阿努比斯與寄宿在自己身體裏的賽特意識對話，探聽到關於恒心的資訊。而總隊長那邊，眾人發現造物守衛的狀態也發生了變化。"}
,[10331]={["key"]=10331,["storyType"]=1,["name"]="第三章-第26节",["beginId"]=1033101,["id"]=10331,["type"]=1,["section_name"]="歸納論證",["desc"]="阿努比斯教導荷魯斯思考尼克羅未來應如何發展，荷魯斯離去後，阿努比斯與出現的「影」交談。總隊長與普羅米修斯提起異變與收束塔的關系，想嘗試獲取收束塔的資料。"}
,[10339]={["key"]=10339,["storyType"]=1,["name"]="第三章-第33节",["beginId"]=1033901,["id"]=10339,["type"]=1,["section_name"]="中斷回路（上）",["desc"]="伊西斯準備破壞軌道電梯與收束塔聯接的部分，卡尼斯、賦格和嵐出現阻止。正在此時，被穆特引爆的機動平臺從正上方墜下。"}
,[10347]={["key"]=10347,["storyType"]=1,["name"]="第三章-第41节",["beginId"]=1034701,["id"]=10347,["type"]=1,["section_name"]="侵吞戰影（下）",["desc"]="開啟瞭解禁模式的漆黑與總隊長擊敗奈芙蒂斯，奈芙蒂斯意識消失，拉重新接管身體。醒來後的拉對總隊長的戰鬥過程念念不忘，表示十分喜愛總隊長，希望總隊長能留在尼克羅。"}
,[20710]={["key"]=20710,["storyType"]=9,["name"]="奇迹之夜活动剧情10",["beginId"]=2071001,["id"]=20710,["type"]=1,["section_name"]="傀儡把戲（上）",["desc"]="緹爾鋒回憶起已成為心結的往事，哀嘆自己又一次沒能救下隊友，她決定代替西爾維婭完成“奇跡之夜”演出。"}
,[10403]={["key"]=10403,["storyType"]=1,["name"]="第四章-第2节",["beginId"]=1040301,["id"]=10403,["type"]=1,["section_name"]="礁石荒灘（上）",["desc"]="降落到第五分隊所在板塊的總隊長沒有遇到第五分隊，與普羅米修斯交談後得知定位出現偏差。斷開通訊後，環境陡然出現異常徵兆，海水中站起大批造物。"}
,[10411]={["key"]=10411,["storyType"]=1,["name"]="第四章-第10节",["beginId"]=1041101,["id"]=10411,["type"]=1,["section_name"]="記憶深處",["desc"]="處理完所有感染造物後，鳴刃感到不安，總隊長詢問為什麽不請求護衛隊幫助，鳴刃解釋自己是當時最早信任偽裝的「研者」的人，被視為板塊的罪人而無法調度護衛隊。"}
,[10419]={["key"]=10419,["storyType"]=1,["name"]="第四章-第18节",["beginId"]=1041901,["id"]=10419,["type"]=1,["section_name"]="失控造物（下）",["desc"]="打敗失控的造物守衛後，總隊長慶幸不是異變。鳴刃好奇詢問異變是什麽，總隊長詳細講述後鳴刃半信半疑，表示從未見過的事情無法全盤相信。"}
,[10427]={["key"]=10427,["storyType"]=1,["name"]="第四章-第24节",["beginId"]=1042701,["id"]=10427,["type"]=1,["section_name"]="光塵飛揚（上）",["desc"]="第五分隊在離開居民區途中發現收束塔出現異常狀態，散發出影響NOVA核心運轉的奇怪塵灰。為了加速逃離，第五分隊成員將旋律扛起離開。總隊長與鳴刃也發現了收束塔的異樣，但仍需要先行關閉管道閥門。"}
,[10435]={["key"]=10435,["storyType"]=1,["name"]="第四章-第31节",["beginId"]=1043501,["id"]=10435,["type"]=1,["section_name"]="孤注一擲（下）",["desc"]="赤夕感染改進後的Σ病毒後，對病毒的加成和能力作出了分析，但很快也被異變所控製，赤夕依靠僅剩的自我意誌繼續向收束塔前行。旋律在即將接近管道閥門時再次被幻覺控製，但在抵抗幻覺後成功完成任務。"}
,[10443]={["key"]=10443,["storyType"]=1,["name"]="第四章-第39节",["beginId"]=1044301,["id"]=10443,["type"]=1,["section_name"]="災禍核心（下）",["desc"]="被擊敗的瑪勒絲試圖求饒，並願意說出自己所知道的，潛伏在地球上的「研者」情報。但總隊長拒絕了她的求饒，徹底破壞了「災禍之獸」的核心。"}
,[20902]={["key"]=20902,["storyType"]=11,["name"]="云端行迹活动剧情3",["beginId"]=2090201,["id"]=20902,["type"]=1,["section_name"]="神秘晶片（下）",["desc"]="擊敗隱藏的低級造物後，眾人在造物身上獲得古怪的晶片，而這枚晶片使用了從未見過的材料。夜暝對眾人產生懷疑，認為為何眾人出現後，就跟隨出現了許多突兀的事情，朝暉出來調停。"}
,[22005]={["key"]=22005,["storyType"]=22,["name"]="星间纪行-奥西里斯",["beginId"]=2200501,["id"]=22005,["type"]=1,["section_name"]="光芒終將升起",["desc"]="阿圖姆為了獲取優勢而選擇與“研者”合作，卻發現淪為傀儡。在“研者”的威逼下，阿圖姆決定與之決裂。阿圖姆逝去後，阿努比斯要求奧西里斯重啟建造副艦的計畫，以抵禦共同敵人。"}
,[10507]={["key"]=10507,["storyType"]=1,["name"]="第五章-第6节",["beginId"]=1050701,["id"]=10507,["type"]=1,["section_name"]="晦暗槍聲（上）",["desc"]="滄及總隊長一幹人等進入指揮中心，在這裏看到了受傷的基地指揮官奧蘭治。在詢問過程中，奧蘭治突然對總隊長喊出意義不明的話語，並驅使擬態造物向其他人發起攻擊。"}
,[10515]={["key"]=10515,["storyType"]=1,["name"]="第五章-第11节",["beginId"]=1051501,["id"]=10515,["type"]=1,["section_name"]="天穹之上（下）",["desc"]="總隊長被造物絆住，處理完造物後稽查者已經將總隊長堵在了通道邊。在與龍弦眼神溝通後，總隊長和龍弦破壞通道干擾稽查者，成功為總隊長爭取到脫逃的機會。"}
,[10523]={["key"]=10523,["storyType"]=1,["name"]="第五章-第19节",["beginId"]=1052301,["id"]=10523,["type"]=1,["section_name"]="陰影盤桓（上）",["desc"]="希恩站在樓頂遠望稽查者，而被塞進同一具玩偶身體的奈芙蒂斯與凱貝潔特則因為主導權而吵架。希恩提出問題後，凱貝潔特給予希恩意見，希恩若有所思。"}
,[20023]={["key"]=20023,["storyType"]=2,["name"]="电影活动11",["beginId"]=2002301,["id"]=20023,["type"]=2,["section_name"]="蘇醒的冥界之主",["desc"]="因為睡神與死神被擊敗，哈迪斯從休眠中醒來。"}
,[10539]={["key"]=10539,["storyType"]=1,["name"]="第五章-第35节",["beginId"]=1053901,["id"]=10539,["type"]=1,["section_name"]="倒懸之地（下）",["desc"]="拷貝完資料後，總隊長以及造物-埃莉諾卻發現地下基地的外部防水屏障被解除，基地很快就會被海水衝擊撕裂，造物-埃莉諾將總隊長帶到逃生艙前，讓總隊長迅速離開。"}
,[20103]={["key"]=20103,["storyType"]=2,["name"]="卡提那个人活动第4节",["beginId"]=2010301,["id"]=20103,["type"]=1,["section_name"]="異變之後",["desc"]="根據普羅米修斯的指引，二人來到結冰深谷之上的聚集地，其中的辛尼好心的告訴二人各種所需要的情報。"}
,[10603]={["key"]=10603,["storyType"]=1,["name"]="第六章-第2节",["beginId"]=1060301,["id"]=10603,["type"]=1,["section_name"]="雪域荒城（上）",["desc"]="三人在乘坐運輸機趕赴北境戰區的途中遭遇怪異造物突襲，總隊長讓洛貝拉兩人先行離開，自己擊敗造物後再行跳傘，降落後意外遇見似乎認識總隊長的神秘武裝少女。"}
,[21206]={["key"]=21206,["storyType"]=14,["name"]="白垩行旅活动剧情7",["beginId"]=2120601,["id"]=21206,["type"]=1,["section_name"]="約定（下）",["desc"]="手指相勾，於是約定就這樣許下。但在妹妹們看不到的地方，還有緊張的備戰，以及……來自盟友的猜疑。"}
,[10619]={["key"]=10619,["storyType"]=1,["name"]="第六章-第11节",["beginId"]=1061901,["id"]=10619,["type"]=1,["section_name"]="舊式機體（上）",["desc"]="總隊長趕赴北境戰區的莫羅斯基地支援，與指揮官斯涅紮娜中校交流，想挖掘關於阿卡斯的消息，但無功而返。"}
,[20215]={["key"]=20215,["storyType"]=3,["name"]="蛛影活动剧情15",["beginId"]=2021501,["id"]=20215,["type"]=1,["section_name"]="替身",["desc"]="遊戲結束，留一下一堆空白，NOVA物質的走私、暮光市的黑暗、以及被埋沒在熱鬧下的真相……"}
,[10635]={["key"]=10635,["storyType"]=1,["name"]="第六章-第27节",["beginId"]=1063501,["id"]=10635,["type"]=1,["section_name"]="險象環生（上）",["desc"]="從幻覺中清醒後，眾人決定先破壞聚合點再去尋找利茲，加快速度奔赴指定位置。"}
,[20311]={["key"]=20311,["storyType"]=5,["name"]="袅韵个人活动12",["beginId"]=2031101,["id"]=20311,["type"]=1,["section_name"]="新生（下）",["desc"]="裊韻與困擾已久的心結和解，向總隊長伸出手。"}
,[10707]={["key"]=10707,["storyType"]=1,["name"]="第七章-第3节",["beginId"]=1070701,["id"]=10707,["type"]=1,["section_name"]="陌生地域（下）",["desc"]="總隊長與弗麗嘉交談時，弗麗嘉發現侵蝕天災將要降臨，帶著總隊長逃往國度邊境。另一邊，阿卡斯發現諾斯板塊出現特別情況，於是把調查諾斯板塊的任務交給了希恩。"}
,[20407]={["key"]=20407,["storyType"]=6,["name"]="糖果活动剧情8",["beginId"]=2040701,["id"]=20407,["type"]=1,["section_name"]="絕不單調（下）",["desc"]="赫爾墨斯打起自己的算盤，卡蒂雅也找到了合適的人選。"}
,[20423]={["key"]=20423,["storyType"]=6,["name"]="糖果活动剧情24",["beginId"]=2042301,["id"]=20423,["type"]=1,["section_name"]="寶藏之地",["desc"]="傳說中藏有索爾達森寶藏的隱秘之地——尼約姆。想要探知寶藏的真相，先要清理掉擋路的造物。"}
,[20503]={["key"]=20503,["storyType"]=7,["name"]="夏日海韵活动剧情3",["beginId"]=2050301,["id"]=20503,["type"]=1,["section_name"]="出碎星記（上）",["desc"]="飛行器即將抵達目的地，眾人聊起了傳說中的“宇宙海怪克拉肯”，不料此時果真遇到意外。"}
,[21702]={["key"]=21702,["storyType"]=19,["name"]="假日共游2",["beginId"]=2170201,["id"]=21702,["type"]=1,["section_name"]="喧鬧都市（上）",["desc"]="來到地球的歲稔為眼前所見的景象而感到新奇，而在此時，卻有造物突然出現並襲擊市民。"}
,[21923]={["key"]=21923,["storyType"]=21,["name"]="异态侵蚀17",["beginId"]=2192301,["id"]=21923,["type"]=1,["section_name"]="追上你",["desc"]="事件解決後數年，皮洛可為了見總隊長，成為了前哨基地的一員——故事就這樣告一段落。皮洛可表示自己已經不只是總隊長的學生，許多事情都可以做了。"}
,[20711]={["key"]=20711,["storyType"]=9,["name"]="奇迹之夜活动剧情11",["beginId"]=2071101,["id"]=20711,["type"]=1,["section_name"]="傀儡把戲（下）",["desc"]="被控制在後臺的凱貝潔特發起襲擊，想要奪取總隊長的肉體。"}
,[10262]={["key"]=10262,["storyType"]=1,["name"]="第二章-第38节",["beginId"]=1026201,["id"]=10262,["type"]=1,["section_name"]="疊加態",["desc"]="維達爾把一切託付給了人類，人類的未來將由『人類』來決定。"}
,[10060]={["type"]=2,["id"]=10060,["desc"]="none",["line"]=10060,["name"]="破盾剧情",["key"]=10060,["storyType"]=1,["section_name"]="none",["beginId"]=1000550}
,[21626]={["key"]=21626,["storyType"]=18,["name"]="意欲地牢17",["beginId"]=2162601,["id"]=21626,["type"]=1,["section_name"]="後日談",["desc"]="你們成功回收了異態體，當你、冕羽還有克拉倫特在撰寫報告時，NOVA手錶突然綻放出耀眼的光芒。光芒散去，瑞絲出現在了你們的面前。原來危急時刻，NOVA手錶將瑞絲吸收、保護——現在你可以說，這一次的任務圓滿完成了。"}
,[21844]={["type"]=1,["id"]=21844,["desc"]="透過廣播也能感受到的怨氣。屠殺線還是和平線？溫柔的卡提那選擇了……",["line"]=20000,["name"]="筑梦热土44",["key"]=21844,["storyType"]=20,["section_name"]="建造電視塔",["beginId"]=2184401}
