,[10324]={["key"]=10324,["storyType"]=1,["name"]="第三章-第19节",["beginId"]=1032401,["id"]=10324,["type"]=1,["section_name"]="前行之路（下）",["desc"]="檢驗過造物殘體的普羅米修斯判斷造物的核心數據有被暴力覆寫的痕跡，總隊長與普羅米修斯回想起過往經歷，判斷尼克羅可能發生了異變。"}
,[21709]={["key"]=21709,["storyType"]=19,["name"]="假日共游9",["beginId"]=2170901,["id"]=21709,["type"]=1,["section_name"]="聲東擊西（下）",["desc"]="由於歲稔體內的NOVA能量一直在流失，需要取出放在折疊空間裏的藥劑，你摸索了一番後，好不容易終於拿出了藥劑。歲稔恢復過來後，決定與你一起去追查異態體造物的下落。"}
,[10340]={["key"]=10340,["storyType"]=1,["name"]="第三章-第34节",["beginId"]=1034001,["id"]=10340,["type"]=1,["section_name"]="中斷回路（下）",["desc"]="被打敗的伊西斯不甘心自己的破壞計劃被中止，趁眾人不註意時凝聚了能量球，破壞了「冥界」系統、收束塔與軌道電梯的連接部分。"}
,[10348]={["key"]=10348,["storyType"]=1,["name"]="第三章-第42节",["beginId"]=1034801,["id"]=10348,["type"]=1,["section_name"]="統治者之威（上）",["desc"]="終於來到阿努比斯跟前，阿努比斯詢問了總隊長和分隊隊員們來到尼克羅的原因，並將自己想與地球方成為盟友的想法告知。但這一切的前提是，總隊長必須證明自己有足夠的實力。"}
,[21707]={["key"]=21707,["storyType"]=19,["name"]="假日共游7",["beginId"]=2170701,["id"]=21707,["type"]=1,["section_name"]="查蹤尋跡（下）",["desc"]="你找到造物所在的座標後，發現造物疑似是針對你的誘餌，在戰鬥後仔細觀察造物結構，發現有被改造過的跡象。"}
,[20712]={["key"]=20712,["storyType"]=9,["name"]="奇迹之夜活动剧情12",["beginId"]=2071201,["id"]=20712,["type"]=1,["section_name"]="昨日重現",["desc"]="凱貝潔特的行為意外導致兩人精神鏈接，總隊長在記憶中看到了從前和西爾維婭的往事，而在狼藉的現實世界中，舞臺已淪為戰場。"}
,[10259]={["key"]=10259,["storyType"]=1,["name"]="第二章-第36节",["beginId"]=1025901,["id"]=10259,["type"]=1,["section_name"]="放逐者",["desc"]="托爾被布倫希爾德放逐，絲卡蒂被維達爾帶走，戰鬥即將迎來尾聲。"}
,[21705]={["key"]=21705,["storyType"]=19,["name"]="假日共游5",["beginId"]=2170501,["id"]=21705,["type"]=1,["section_name"]="夜街驚變（下）",["desc"]="擊敗造物後，你和歲稔意外發現造物竟然擁有極其少見的特殊能力。而在造物逃逸後，你們與被救下的市民夏洛特交談，得知關於造物的線索。歲稔交給你一個特殊裝置，這個裝置可以幫你追蹤到造物的位置。"}
,[21202]={["key"]=21202,["storyType"]=14,["name"]="白垩行旅活动剧情3",["beginId"]=2120201,["id"]=21202,["type"]=1,["section_name"]="白堊紀（下）",["desc"]="白堊紀的日常艱苦而溫馨。首領雷克斯安頓好妹妹們後，決定會見來訪的兩位客人。"}
,[21703]={["key"]=21703,["storyType"]=19,["name"]="假日共游3",["beginId"]=2170301,["id"]=21703,["type"]=1,["section_name"]="喧鬧都市（下）",["desc"]="擊敗造物後，市民討論起最近常有造物擄人的情況，你聽到後有些在意，但還是先帶歲稔前往NERI支部登記，歲稔的武裝被裝上限制器，無法使用。"}
,[10404]={["key"]=10404,["storyType"]=1,["name"]="第四章-第3节",["beginId"]=1040401,["id"]=10404,["type"]=1,["section_name"]="礁石荒灘（下）",["desc"]="總隊長與少女鳴刃合作擊敗造物後，從鳴刃這得知了天階原的情況，並向鳴刃請求幫助。另一邊，第五分隊為了避開跟蹤電磁波通訊而來的造物們，被迫毀掉通訊器，而超空間通訊器也失效而無法使用。"}
,[20808]={["key"]=20808,["storyType"]=10,["name"]="觅己归途活动剧情5",["beginId"]=2080801,["id"]=20808,["type"]=1,["section_name"]="風土人情（下）",["desc"]="刺蝽提議直接找幫派聯盟的首領瞭解情況。"}
,[10420]={["key"]=10420,["storyType"]=1,["name"]="第四章-第19节",["beginId"]=1042001,["id"]=10420,["type"]=1,["section_name"]="詭譎顏色",["desc"]="旋律繼續沈淪於夢中，而涅毒與女王蜂對話，指出女王蜂與白色人影到底在密謀什麽。女王蜂將自己所知全部說出，並將空投艙出事的懷疑方向指向了內部人員。總隊長與鳴刃在休憩時提及鳴刃所戴面具，得知經過後勸說鳴刃放下心結，將真相告知雪華。"}
,[10428]={["key"]=10428,["storyType"]=1,["name"]="第四章-第25节",["beginId"]=1042801,["id"]=10428,["type"]=1,["section_name"]="光塵飛揚（下）",["desc"]="熔鑠想追上總隊長和鳴刃，將重鑄後的武器交給鳴刃，卻在收束塔異樣出現後產生了異變。"}
,[10436]={["key"]=10436,["storyType"]=1,["name"]="第四章-第32节",["beginId"]=1043601,["id"]=10436,["type"]=1,["section_name"]="敵潮洶湧（上）",["desc"]="總隊長與鳴刃在異變造物之中艱難前行，漆黑的意識詢問是否需要幫助，總隊長暫時拒絕，並說需要的時候會呼喚漆黑。"}
,[10444]={["key"]=10444,["storyType"]=1,["name"]="第四章-第40节",["beginId"]=1044401,["id"]=10444,["type"]=2,["section_name"]="none",["desc"]="none"}
,[21911]={["key"]=21911,["storyType"]=21,["name"]="异态侵蚀6",["beginId"]=2191101,["id"]=21911,["type"]=1,["section_name"]="副所長（上）",["desc"]="皮洛可和總隊長救下副所長維拉，並且得知這裡洩露的是政府早就禁止研究的異態體。在維拉的幫助下，眾人向妮娜所在的位置出發。"}
,[20904]={["key"]=20904,["storyType"]=11,["name"]="云端行迹活动剧情5",["beginId"]=2090401,["id"]=20904,["type"]=1,["section_name"]="衍生造物（下）",["desc"]="擊敗這些造物後，女王蜂從造物身上獲得第二枚晶片，並發現造物身上有涅毒的標記，猜想晶片是涅毒為了傳遞消息而嵌入造物身體裡。"}
,[21625]={["key"]=21625,["storyType"]=18,["name"]="意欲地牢16",["beginId"]=2162501,["id"]=21625,["type"]=1,["section_name"]="朋友",["desc"]="瑞絲戰敗之後把能量珠交給了你們。這時你們才知道，異變一旦解除瑞絲也會隨之消失。瑞絲為了讓你們毫無顧慮地解除異變，選擇扮黑臉與你們戰鬥。最終瑞絲心滿意足地與空間一同消失。"}
,[21624]={["key"]=21624,["storyType"]=18,["name"]="意欲地牢15",["beginId"]=2162401,["id"]=21624,["type"]=1,["section_name"]="真正的她（下）",["desc"]="你們來到最後一個房間，找到最後的能量珠——瑞絲的遺骸。你們準備回收時，瑞絲突然出手阻止，並揚言要把所有人留在地下空間……你們與瑞絲的戰鬥已經無法避免。"}
,[21623]={["key"]=21623,["storyType"]=18,["name"]="意欲地牢14",["beginId"]=2162301,["id"]=21623,["type"]=1,["section_name"]="真正的她（上）",["desc"]="你和冕羽成功逃離後，眾人終於來到最後一個房間的門前。"}
,[21621]={["key"]=21621,["storyType"]=18,["name"]="意欲地牢13",["beginId"]=2162101,["id"]=21621,["type"]=1,["section_name"]="起點（下）",["desc"]="在索菲亞的幫助下，冕羽解開了心結，意識到好奇心正是自己所有慾望的起點。這一次，冕羽總算能和母親好好告別。"}
,[22007]={["key"]=22007,["storyType"]=22,["name"]="星间纪行-奥丁",["beginId"]=2200701,["id"]=22007,["type"]=1,["section_name"]="對於存在的窺探",["desc"]="奧丁受古爾薇格預言的啟發，萌生了對於永恆生命的追求，弗麗嘉作為實驗品而接受解構。在窺探“研者”外圍基地時，弗麗嘉被重傷，奧丁將她帶回諾斯板塊，並表示自己會延續弗麗嘉的生命。"}
,[10508]={["key"]=10508,["storyType"]=1,["name"]="第五章-第7节",["beginId"]=1050801,["id"]=10508,["type"]=1,["section_name"]="晦暗槍聲（下）",["desc"]="奧蘭治重傷離世，此時擔任NSS司長的伊德海拉趕到，拘下總隊長及其他涉事軍官。此時帕科薩市上方的空間門成型，卻降臨了許多高等級造物及稽查者，城市進入警報狀態。"}
,[10516]={["key"]=10516,["storyType"]=1,["name"]="第五章-第12节",["beginId"]=1051601,["id"]=10516,["type"]=1,["section_name"]="災禍門扉（上）",["desc"]="總隊長在基地出口等待稽查者跟上時，與洛貝拉進行通話，詢問洛貝拉是否知道哪里有智慧女神的塑像，洛貝拉給出回答。總隊長道謝後，洛貝拉詢問總隊長為何不介意自己沒有來支援，總隊長表示自己相信洛貝拉肯定是有事才不能前來。"}
,[10524]={["key"]=10524,["storyType"]=1,["name"]="第五章-第20节",["beginId"]=1052401,["id"]=10524,["type"]=1,["section_name"]="陰影盤桓（下）",["desc"]="艾格與納格陵交談，告知因為身份原因無法處理一些灰色地帶的事情，需要借助桑格維斯幫的勢力。納格陵答允，但告訴艾格使用什麼手段是桑格維斯的事情，艾格無權過問。艾格思忖後答應。"}
,[10532]={["key"]=10532,["storyType"]=1,["name"]="第五章-第28节",["beginId"]=1053201,["id"]=10532,["type"]=1,["section_name"]="縱深區域（下）",["desc"]="緹爾鋒向總隊長確認是否有應對稽查者的備案，總隊長如實回答。爾後眾人將巨型稽查者引到廢棄貧民窟，借複雜地形各自分開。"}
,[10540]={["key"]=10540,["storyType"]=1,["name"]="第五章-第36节",["beginId"]=1054001,["id"]=10540,["type"]=1,["section_name"]="冰山一角（上）",["desc"]="危機干預小組眾人仍在努力控制稽查者的行進速度及路線，為昆侖的新武裝爭取蓄能時間。而另一邊的昆侖目睹同伴的努力，產生了自我懷疑的情緒。"}
,[21617]={["key"]=21617,["storyType"]=18,["name"]="意欲地牢10",["beginId"]=2161701,["id"]=21617,["type"]=1,["section_name"]="何為正確（上）",["desc"]="冕羽和克拉倫特因為冕羽的事情吵了起來。你阻止她們爭吵的時候，冕羽表示要為大家做一頓飯。吃完飯後，眾人情緒也逐漸穩定了下來。飯後冕羽與你談心，兩人關係更近一步。"}
,[21615]={["key"]=21615,["storyType"]=18,["name"]="意欲地牢9",["beginId"]=2161501,["id"]=21615,["type"]=1,["section_name"]="放縱（下）",["desc"]="你與冕羽被困在不進行親密接觸就出不去的房間。隨著親密接觸的等級越來越高，你們之間的氛圍也越來越曖昧。在最後關頭，克拉倫特及時登場。"}
,[21112]={["key"]=21112,["storyType"]=13,["name"]="虚海奇谭活动剧情7",["beginId"]=2111201,["id"]=21112,["type"]=1,["section_name"]="封閉傷痛（上）",["desc"]="眾人來到伊盧森島的森林挑戰黯傷天王，黯傷天王在觸碰到哈托莉後，使哈托莉陷入了無法解除的自卑狀態。同時，總隊長還遇到前哨基地臨時工——梅尼。在梅尼的幫助下，大家開始制定戰術。"}
,[20105]={["key"]=20105,["storyType"]=2,["name"]="卡提那个人活动第6节",["beginId"]=2010501,["id"]=20105,["type"]=1,["section_name"]="雪域空地",["desc"]="沒有積雪的曠野上，突然開啟的傳送門，沒頭沒尾的友情提示，即使得知了%s消失的地方，最終還是決定前往收束塔。"}
,[21609]={["key"]=21609,["storyType"]=18,["name"]="意欲地牢5",["beginId"]=2160901,["id"]=21609,["type"]=1,["section_name"]="克己（下）",["desc"]="你們來到了克拉倫特的慾望空間，在這裡面你們看到克拉倫特和你的冒牌貨。冒牌貨對話進行到關鍵片段時，克拉倫特上前將其斬殺，得到了一顆能量珠。冕羽瞭解克拉倫特的想法後，暗自下定決心。"}
,[21212]={["key"]=21212,["storyType"]=14,["name"]="白垩行旅活动剧情13",["beginId"]=2121201,["id"]=21212,["type"]=1,["section_name"]="赴火（上）",["desc"]="泰坦型造物，它的身軀遮蔽天空，它的步伐震撼大地，它……可以被戰勝嗎？你將替人類給出答案。"}
,[21509]={["key"]=21509,["storyType"]=17,["name"]="裂空活动10",["beginId"]=2150901,["id"]=21509,["type"]=1,["section_name"]="明日歸途",["desc"]="假期結束了。相比起你的平靜，身旁的少女顯然仍沉浸在記憶的片段中……"}
,[21507]={["key"]=21507,["storyType"]=17,["name"]="裂空活动8",["beginId"]=2150701,["id"]=21507,["type"]=1,["section_name"]="黃沙之下（上）",["desc"]="幻象逐漸逝去。裂空駕駛著熟悉的武裝，同內心的軟弱訣別，並踏入真正的戰場。"}
,[21208]={["key"]=21208,["storyType"]=14,["name"]="白垩行旅活动剧情9",["beginId"]=2120801,["id"]=21208,["type"]=1,["section_name"]="誰是獵物（上）",["desc"]="在會合點的廢棄倉庫遭遇機械造物伏擊，變故陡生！"}
,[10620]={["key"]=10620,["storyType"]=1,["name"]="第六章-第12节",["beginId"]=1062001,["id"]=10620,["type"]=1,["section_name"]="舊式機體（下）",["desc"]="總隊長在幫莫羅斯基地擊退來襲的敵人後，意外發現有部分敵人竟然是“流星工業”淘汰的最早一批武裝自律人形，想要根據通訊鏈反向追溯敵方位置。"}
,[10628]={["key"]=10628,["storyType"]=1,["name"]="第六章-第20节",["beginId"]=1062801,["id"]=10628,["type"]=1,["section_name"]="編綴成型",["desc"]="離開基地後總隊長眾人獲得了海底建築設計圖和模型設計圖，經過洛貝拉分析後，得出了“重塑計畫”目前的進度和情況，並決定從能量聚合點入手應對。"}
,[10636]={["key"]=10636,["storyType"]=1,["name"]="第六章-第28节",["beginId"]=1063601,["id"]=10636,["type"]=1,["section_name"]="險象環生（下）",["desc"]="破壞佩謝拉密巢的主控臺後，薩斯塔留言聚合點下方有極其強烈的能量波動，讓眾人趕緊逃離。總隊長讓其他人先行離開，自己留下尋找失蹤的利茲。"}
,[21505]={["key"]=21505,["storyType"]=17,["name"]="裂空活动6",["beginId"]=2150501,["id"]=21505,["type"]=1,["section_name"]="心淵裂隙（下）",["desc"]="以釣魚比賽為餌，星墜猝然將裂空推下深潭……"}
,[21503]={["key"]=21503,["storyType"]=17,["name"]="裂空活动4",["beginId"]=2150301,["id"]=21503,["type"]=1,["section_name"]="意外的體檢",["desc"]="總隊長的專業體驗，診斷出裂空患有名為“金字塔詛咒”的未知疾病。"}
,[21304]={["key"]=21304,["storyType"]=15,["name"]="魔导少女活动剧情3",["beginId"]=2130401,["id"]=21304,["type"]=1,["section_name"]="魔導少女（下）",["desc"]="伊根輕而易舉擊敗了造物，眾人為了一次性解決問題，決定出發前去搗毀位於地球的造物工廠，並且打敗造物工廠的建造者——黑暗女帝。"}
,[21501]={["key"]=21501,["storyType"]=17,["name"]="裂空活动2",["beginId"]=2150101,["id"]=21501,["type"]=1,["section_name"]="遺忘之地",["desc"]="遭遇風暴後，裂空在綠洲中醒來，見到了昔日的好友星墜。得知救援經過，總隊長已提前半日獲救，二人前往綠洲中的臨時基地。"}
,[21422]={["key"]=21422,["storyType"]=16,["name"]="冬日速递17",["beginId"]=2142201,["id"]=21422,["type"]=1,["section_name"]="心中的夢想",["desc"]="前哨基地紀念日順利舉行，赫格尼向你訴說心聲，並且和大家一起看完了煙花表演。當天晚上，她再次溜進你的房間，你決定好好教育一下她。"}
,[21419]={["key"]=21419,["storyType"]=16,["name"]="冬日速递15",["beginId"]=2141901,["id"]=21419,["type"]=1,["section_name"]="最終防衛（上）",["desc"]="赫格尼和喵喵纏住了阿曼，然而依舊落於下風。危急時刻眾人趕到，通過特製煙花削弱阿曼，開始了最後的戰鬥。"}
,[21418]={["key"]=21418,["storyType"]=16,["name"]="冬日速递14",["beginId"]=2141801,["id"]=21418,["type"]=1,["section_name"]="關門打狗（下）",["desc"]="作戰執行過程中發生意外，阿曼開始反過來吸收視界的能量。無奈之下只能啟動緊急彈出程式，將所有人彈出視界。為了和阿曼一起被傳送到同一個地方，赫格尼和喵喵沖向了阿曼。"}
,[20017]={["key"]=20017,["storyType"]=2,["name"]="电影活动08",["beginId"]=2001701,["id"]=20017,["type"]=1,["section_name"]="引力倒錯",["desc"]="突如其來的飛行造物讓眾人跌入蟲洞，來到暗面。"}
,[10708]={["key"]=10708,["storyType"]=1,["name"]="第七章-第4节",["beginId"]=1070801,["id"]=10708,["type"]=1,["section_name"]="尤克希爾（上）",["desc"]="總隊長與弗麗嘉逃到邊境後遇見被任命為斯瓦塔爾夫海姆女王的卡提那，卡提那想要喊出“總隊長”時，發現自己遭受到了限制，只能用名字稱呼總隊長。"}
,[21416]={["key"]=21416,["storyType"]=16,["name"]="冬日速递12",["beginId"]=2141601,["id"]=21416,["type"]=1,["section_name"]="阿曼的傳說",["desc"]="阿曼的下一個目標是物流運輸車，眾人為了擊退阿曼，開始作戰會議。"}
,[10724]={["key"]=10724,["storyType"]=1,["name"]="第七章-第15节",["beginId"]=1072401,["id"]=10724,["type"]=1,["section_name"]="裂隙之路（下）",["desc"]="希恩仍在神秘區域中尋找出路，神秘聲音突然從腦海中出現，勾起了希恩被特意埋藏的記憶。"}
,[20425]={["key"]=20425,["storyType"]=6,["name"]="糖果活动剧情26",["beginId"]=2042501,["id"]=20425,["type"]=1,["section_name"]="決不繞路（下）",["desc"]="那位的登場已經就緒，現在只需要烏斯懷亞簡單的語言鋪墊。"}
,[21415]={["key"]=21415,["storyType"]=16,["name"]="冬日速递11",["beginId"]=2141501,["id"]=21415,["type"]=1,["section_name"]="危險分子（下）",["desc"]="奧西里斯分析碎片的同時，赤狼將小造物的語言模組修好。從小造物和奧西里斯口中得知，神秘造物的真身是阿曼，而小造物喵喵是阿曼的從屬造物。阿曼每隔十幾年，它就會為了補充能量，開始襲擊世界各地。就在眾人談話間，阿曼出現了。"}
,[21412]={["key"]=21412,["storyType"]=16,["name"]="冬日速递9",["beginId"]=2141201,["id"]=21412,["type"]=1,["section_name"]="托爾捕獲作戰（下）",["desc"]="托爾拼盡全力掙扎，但還是被你們成功抓捕。當你們回去的時候，正好絲卡蒂也完成了碎片的解析，得知碎片的構成材料來自尼克羅。"}
,[21410]={["key"]=21410,["storyType"]=16,["name"]="冬日速递8",["beginId"]=2141001,["id"]=21410,["type"]=1,["section_name"]="托爾捕獲作戰（上）",["desc"]="解開誤會後，你們把找到的造物碎片交給絲卡蒂分析。利用絲卡蒂分析的這段時間，你們組成臨時小隊開始抓捕罷工的托爾。"}
,[21409]={["key"]=21409,["storyType"]=16,["name"]="冬日速递7",["beginId"]=2140901,["id"]=21409,["type"]=1,["section_name"]="逃亡者（下）",["desc"]="在倉庫區域調查的過程中，布倫希爾德突然出現。托爾逃跑後，布倫希爾德把你們當成托爾的共犯帶走。"}
,[20505]={["key"]=20505,["storyType"]=7,["name"]="夏日海韵活动剧情5",["beginId"]=2050501,["id"]=20505,["type"]=1,["section_name"]="孤泳者集結",["desc"]="赤溟邀請眾人用捕魚比賽的方式進行探索任務，並將收獲的海洋生物放進她的臨時實驗室。"}
,[21400]={["key"]=21400,["storyType"]=16,["name"]="冬日速递1",["beginId"]=2140001,["id"]=21400,["type"]=1,["section_name"]="新隊員的煩惱",["desc"]="提澤納希望你能幫助赫格尼，而你在加深對赫格尼的瞭解後，表示自己願意幫助她。赫格尼為了表達自己求助別人的誠意，在你休息的時候偷偷溜進了你的房間。"}
,[10626]={["key"]=10626,["storyType"]=1,["name"]="第六章-第18节",["beginId"]=1062601,["id"]=10626,["type"]=1,["section_name"]="不可拋卻（上）",["desc"]="總隊長決定和利茲，旋流及翼蓑等人前往探測後顯示巨量NOVA能量反應的座標進行調查。"}
,[10220]={["key"]=10220,["storyType"]=1,["name"]="第二章-第10节",["beginId"]=1022001,["id"]=10220,["type"]=1,["section_name"]="聯合軍",["desc"]="女武神長布倫希爾德爽快地同意了合作請求，但她也提出了一個條件。"}
,[21213]={["key"]=21213,["storyType"]=14,["name"]="白垩行旅活动剧情14",["beginId"]=2121301,["id"]=21213,["type"]=1,["section_name"]="赴火（下）",["desc"]="龍矢驅散了風雪，令瑞威大地重見天光。在回NERI述職前，你同魁紂——這位身懷異能，卻心有彷徨的少女立下約定：一場旅途的結束，將是下一場更精彩旅途的開端。"}
,[21608]={["key"]=21608,["storyType"]=18,["name"]="意欲地牢4",["beginId"]=2160801,["id"]=21608,["type"]=1,["section_name"]="克己（上）",["desc"]="你們安撫冕羽的情緒後，決定下一次由克拉倫特開門。開門後你們來到某個大都市的街道上。"}
,[20601]={["key"]=20601,["storyType"]=8,["name"]="幻梦逸旅活动剧情2",["beginId"]=2060101,["id"]=20601,["type"]=1,["section_name"]="別失去理智",["desc"]="調查人員沒有找到非法製品的證據，工廠老闆蒂娜和人員發生爭執。C.C.C.脫離隊伍找到暗門，卻沒想到掉入地下隱秘空間。G.G.G.發現C.C.C.不見後，讓總隊長去尋找C.C.C.，並說這是對總隊長的考驗。另一邊，掉入地下的C.C.C.遇見孤兒溫蒂。"}
,[21211]={["key"]=21211,["storyType"]=14,["name"]="白垩行旅活动剧情12",["beginId"]=2121101,["id"]=21211,["type"]=1,["section_name"]="家人（下）",["desc"]="是藥物，還是怒火支持著雷克斯戰鬥？總之敵人被暫時打退，幕後的造物終將顯出它的真身……"}
,[21210]={["key"]=21210,["storyType"]=14,["name"]="白垩行旅活动剧情11",["beginId"]=2121001,["id"]=21210,["type"]=1,["section_name"]="家人（上）",["desc"]="且戰且退至倉庫中，不料此處也埋伏著隱匿型造物。魁紂為救雷克斯正面扛下炮火，生命垂危……"}
,[21209]={["key"]=21209,["storyType"]=14,["name"]="白垩行旅活动剧情10",["beginId"]=2120901,["id"]=21209,["type"]=1,["section_name"]="誰是獵物（下）",["desc"]="戰端一開，造物的攻擊將永不停歇。白堊紀已陷入危急之中，你的計畫能否迎來轉機？"}
,[21204]={["key"]=21204,["storyType"]=14,["name"]="白垩行旅活动剧情5",["beginId"]=2120401,["id"]=21204,["type"]=1,["section_name"]="狩獵（下）",["desc"]="魁紂和菲利普一同進山狩獵，成果頗豐。二人敞開心扉的交談也無疑拉近了彼此的距離。"}
,[21704]={["key"]=21704,["storyType"]=19,["name"]="假日共游4",["beginId"]=2170401,["id"]=21704,["type"]=1,["section_name"]="夜街驚變（上）",["desc"]="在夜市上，歲稔對地球的食物十分好奇並嘗試了不少，之後你與歲稔走到另一片街區時，意外撞見造物意圖擄走市民。"}
,[21131]={["key"]=21131,["storyType"]=13,["name"]="虚海奇谭活动剧情17",["beginId"]=2113101,["id"]=21131,["type"]=1,["section_name"]="重逢",["desc"]="眾人順利回到現實世界，伏特加和芭貝拉也被一同傳送到前哨基地。提澤納醒來後總隊長前去探望，發現哈托莉的存儲裝置發揮作用，將提澤納的記憶成功保留。總隊長實現與提澤納的約定，帶著大家去了真正的海邊。"}
,[20713]={["key"]=20713,["storyType"]=9,["name"]="奇迹之夜活动剧情13",["beginId"]=2071301,["id"]=20713,["type"]=1,["section_name"]="俄羅斯轉盤（上）",["desc"]="面對又一次相似的命令，緹爾鋒對著疑似被凱貝潔特奪舍了意識的同伴，忍痛地舉起了槍。"}
,[21129]={["key"]=21129,["storyType"]=13,["name"]="虚海奇谭活动剧情16",["beginId"]=2112901,["id"]=21129,["type"]=1,["section_name"]="真實自我（下）",["desc"]="戰鬥結束，女王落敗。提澤納流露心聲，與女王相互理解，二者重新歸一。離開虛擬空間前，提澤納坦白這段時間的記憶不會保留。總隊長和提澤納許下約定，答應會帶她去真正的海邊。"}
,[21128]={["key"]=21128,["storyType"]=13,["name"]="虚海奇谭活动剧情15",["beginId"]=2112801,["id"]=21128,["type"]=1,["section_name"]="真實自我（上）",["desc"]="見到女王後提澤納向大家坦白，她就是前哨基地的新隊員。女王也坦言，自己是提澤納切割分離的負面情緒化身，而提澤納的目的是通過消滅女王，徹底殺死自己的負面情緒。女王為了反抗自己的命運，與眾人展開決戰戰鬥。"}
,[10527]={["key"]=10527,["storyType"]=1,["name"]="第五章-第23节",["beginId"]=1052701,["id"]=10527,["type"]=1,["section_name"]="引導行動（下）",["desc"]="危機干預小組眾人回到戰場後，發現稽查者的防禦力場有崩潰現象，但稽查者利用造物核心為自己補充了能量，這是以往機械天使從未有過的行為。"}
,[21800]={["key"]=21800,["storyType"]=20,["name"]="筑梦热土1",["beginId"]=2180001,["id"]=21800,["type"]=1,["section_name"]="尼克羅假日（上）",["desc"]="應阿努比斯的邀請，前哨基地組建了一支觀光交流團前往尼可羅。然而事不遂人願，旅途一開始就發生了出乎意料的展開……"}
,[21816]={["key"]=21816,["storyType"]=20,["name"]="筑梦热土16",["beginId"]=2181601,["id"]=21816,["type"]=1,["section_name"]="狂歡籌備（下）",["desc"]="危機悄然出現……拉和貝蒂斯們隱瞞了什麼？"}
,[20809]={["key"]=20809,["storyType"]=10,["name"]="觅己归途活动剧情6",["beginId"]=2080901,["id"]=20809,["type"]=1,["section_name"]="考察尋蹤（上）",["desc"]="刺蝽和總隊長在考察夜鶯鎮情況的同時，找到幫派聯盟的據點。"}
,[21127]={["key"]=21127,["storyType"]=13,["name"]="虚海奇谭活动剧情14",["beginId"]=2112701,["id"]=21127,["type"]=1,["section_name"]="夜空孤星（下）",["desc"]="總隊長看完阿詩蒂的記憶後，通往女王所在地——中央花園的道路打開了。於是眾人一起向中央花園出發。"}
,[21125]={["key"]=21125,["storyType"]=13,["name"]="虚海奇谭活动剧情13",["beginId"]=2112501,["id"]=21125,["type"]=1,["section_name"]="夜空孤星（上）",["desc"]="第二天，提澤納和總隊長在其他人的幫助下，來到了夜星天王的面前。提澤納發現，真正的夜星天王把錄音裝置和女王的力量留下後就離開了。於是提澤納把最後的日記殘頁交給了總隊長。"}
,[21123]={["key"]=21123,["storyType"]=13,["name"]="虚海奇谭活动剧情12",["beginId"]=2112301,["id"]=21123,["type"]=1,["section_name"]="逐愛之人（下）",["desc"]="提澤納因為總隊長答應和劫掠天王約會而吃醋，於是總隊長答應之後會帶著大家一起出去玩。晚上，女王和總隊長交流後，決定為總隊長恢復被封鎖的記憶。"}
,[10056]={["type"]=2,["id"]=10056,["desc"]="none",["line"]=10056,["name"]="第三幕1",["key"]=10056,["storyType"]=1,["section_name"]="none",["beginId"]=1005601}
,[21912]={["key"]=21912,["storyType"]=21,["name"]="异态侵蚀7",["beginId"]=2191201,["id"]=21912,["type"]=1,["section_name"]="副所長（下）",["desc"]="眾人找到妮娜，並且與所長希羅通過投影見面。對話後眾人決定繼續前進找到希羅，並且阻止她的陰謀。"}
,[20905]={["key"]=20905,["storyType"]=11,["name"]="云端行迹活动剧情6",["beginId"]=2090501,["id"]=20905,["type"]=1,["section_name"]="繁美花林（上）",["desc"]="來到白鳥喜歡待著的另一個地方後，眾人正以為沒有任何收穫，卻聽到了武裝開火的響動。循聲過去後發現被造物包圍的白鰭。"}
,[21117]={["key"]=21117,["storyType"]=13,["name"]="虚海奇谭活动剧情9",["beginId"]=2111701,["id"]=21117,["type"]=1,["section_name"]="坦誠相待（上）",["desc"]="總隊長發現這段記憶與上一段是相連的。總結會議中，芭貝拉向大家講述了自己的過去。之後哈托莉在私底下透露，總隊長的記憶缺失可能是人為造成的。到了夜晚，總隊長在海邊再次遇到了神秘人。"}
,[21115]={["key"]=21115,["storyType"]=13,["name"]="虚海奇谭活动剧情8",["beginId"]=2111501,["id"]=21115,["type"]=1,["section_name"]="封閉傷痛（下）",["desc"]="在一番戰鬥後，芭貝拉成功接觸黯傷天王，並助其解開心結。阿詩蒂的日記殘頁也隨之再次出現。"}
,[21109]={["key"]=21109,["storyType"]=13,["name"]="虚海奇谭活动剧情6",["beginId"]=2110901,["id"]=21109,["type"]=1,["section_name"]="日記殘頁",["desc"]="總隊長通過紙張，看到了小女孩阿詩蒂的記憶。作戰總結會議後，提澤納為總隊長調整了體內的情緒能量，但總隊長感覺身體依舊受到限制。總隊長晚上外出散步時，遇到和提澤納長得一模一樣的神秘人。"}
,[10108]={["key"]=10108,["storyType"]=1,["name"]="第一章-第7节",["beginId"]=1010801,["id"]=10108,["type"]=1,["section_name"]="交易",["desc"]="回到馱獸內的眾人見識到了碎星原住民所面臨的災難，甦醒的雅典娜解釋著情況，並提出交易。"}
,[22008]={["key"]=22008,["storyType"]=22,["name"]="星间纪行-乌鲁鲁",["beginId"]=2200801,["id"]=22008,["type"]=1,["section_name"]="販賣機旁的奇遇",["desc"]="塔莉婭因為擔負上部族生計而發愁，在困窘時卻意外結識藍羚，經過武裝測試後加入探索隊，獲得代號“烏魯魯”。之後在訓練時被引薦給咎瓦尤斯，接下擔任護衛的委託。"}
,[21001]={["key"]=21001,["storyType"]=12,["name"]="朝花夕誓活动剧情2",["beginId"]=2100101,["id"]=21001,["type"]=1,["section_name"]="所憧憬的（上）",["desc"]="灼碧為各人分派任務，銀羽想要擔任主要輸出手的位置，但灼碧看出銀羽還不能穩定控制同調，婉拒了讓她冒險。"}
,[10005]={["key"]=10005,["storyType"]=1,["name"]="序章-第3节",["beginId"]=1000401,["id"]=10005,["type"]=1,["section_name"]="疑心",["desc"]="目標中樞近在眼前，此時卻突然出現了大批遊蕩造物，試圖阻攔你們前進的腳步。"}
,[10013]={["key"]=10013,["storyType"]=1,["name"]="序章-第11节",["beginId"]=1001001,["id"]=10013,["type"]=1,["section_name"]="總隊長的意義",["desc"]="探索隊的五支分隊在投送後遇到不明狀況失聯，總隊長決定親身前往搜救。"}
,[10116]={["key"]=10116,["storyType"]=1,["name"]="第一章-第14节",["beginId"]=1011601,["id"]=10116,["type"]=1,["section_name"]="循跡",["desc"]="雅典娜帶著關著阿瑞斯的蛹室來到了宮殿的玉座，尋找進行曲的位置，但數量眾多，無奈只能使用最笨的辦法——把能量低的都放出來。"}
,[10120]={["key"]=10120,["storyType"]=1,["name"]="第一章-第18节",["beginId"]=1012001,["id"]=10120,["type"]=1,["section_name"]="妖精",["desc"]="根據赫爾墨斯的情報，%s眾人來到銀羽飛行的必行路線利用烽煙告知其位置，妖精終於著陸，但烽煙能吸引的不只是妖精。"}
,[21012]={["key"]=21012,["storyType"]=12,["name"]="朝花夕誓活动剧情12",["beginId"]=2101201,["id"]=21012,["type"]=1,["section_name"]="應銘記的（下）",["desc"]="任務完結後總隊長與卡梅爾眾人通話，銀羽依然念念不忘想要正面迎擊敵人，被灼碧教訓。回到前哨基地後，灼碧與總隊長友好交談，希望之後會有更多合作和愉快的記憶。"}
,[21011]={["key"]=21011,["storyType"]=12,["name"]="朝花夕誓活动剧情11",["beginId"]=2101101,["id"]=21011,["type"]=1,["section_name"]="應銘記的（上）",["desc"]="巨蠍呼喚了大批造物蟲群，卡梅爾眾人面對數量眾多的蟲群頗為苦惱，銀羽自告奮勇發揮速度優勢，把自己作為誘餌，把造物蟲群引到特定區域後引爆微波炸彈殲滅它們。"}
,[10053]={["type"]=2,["id"]=10053,["desc"]="none",["line"]=10053,["name"]="第一幕2",["key"]=10053,["storyType"]=1,["section_name"]="none",["beginId"]=1005301}
,[20106]={["key"]=20106,["storyType"]=2,["name"]="卡提那个人活动第7节",["beginId"]=2010601,["id"]=20106,["type"]=1,["section_name"]="駭人的異星灰域",["desc"]="奧林匹斯遙遠的距離，剛好遇上了“順路”的碎星馱獸，其中碎星商會的會員出於“好意”載了二人一程。"}
