,[20005]={["key"]=20005,["storyType"]=2,["name"]="电影活动03-2",["beginId"]=2000501,["id"]=20005,["type"]=2,["section_name"]="秘密迷宮",["desc"]="虛擬場景中，開始戰鬥。"}
,[20401]={["key"]=20401,["storyType"]=6,["name"]="糖果活动剧情2",["beginId"]=2040101,["id"]=20401,["type"]=1,["section_name"]="黑兔少女",["desc"]="你從代號“烏斯懷亞”的少女臉上，看到了緊張與不安。但為什麼，她眼中卻又有著溫柔與依戀？"}
,[20409]={["key"]=20409,["storyType"]=6,["name"]="糖果活动剧情10",["beginId"]=2040901,["id"]=20409,["type"]=1,["section_name"]="未知方向（上）",["desc"]="要書寫愛與勇氣的故事，首要是見到造物時不能逃跑。"}
,[20417]={["key"]=20417,["storyType"]=6,["name"]="糖果活动剧情18",["beginId"]=2041701,["id"]=20417,["type"]=1,["section_name"]="滿懷好奇（上）",["desc"]="渦流醒來，將舞臺移至幕後，荒誕的發展還在持續。"}
,[10501]={["key"]=10501,["storyType"]=1,["name"]="第五章-第1节",["beginId"]=1050101,["id"]=10501,["type"]=1,["section_name"]="冗長會議",["desc"]="中央政司召開會議，滄離開會場後遇到阿卡斯，兩人短暫交談。總隊長返回地球後，被全副武裝的NSS人員包圍降落艙，並被告知暫停職務，等候接受調查。"}
,[21002]={["key"]=21002,["storyType"]=12,["name"]="朝花夕誓活动剧情3",["beginId"]=2100201,["id"]=21002,["type"]=1,["section_name"]="所憧憬的（下）",["desc"]="銀羽回想起灼碧曾告訴自己的優勢，但銀羽一直不願意接受這個優點，認為一旦選擇速度優勢，自己過往的努力訓練就白費了。"}
,[10517]={["key"]=10517,["storyType"]=1,["name"]="第五章-第13节",["beginId"]=1051701,["id"]=10517,["type"]=1,["section_name"]="災禍門扉（下）",["desc"]="面對接近的稽查者，總隊長嘗試詢問它為什麼對特化核心如此執著，稽查者回答是為了進化變得更完善。在得到答案後，總隊長引著稽查者前往下一個目標點。"}
,[10525]={["key"]=10525,["storyType"]=1,["name"]="第五章-第21节",["beginId"]=1052501,["id"]=10525,["type"]=1,["section_name"]="同路歧行",["desc"]="使用電磁陷阱禁錮稽查者後，危機干預小組得以暫時休息，總隊長擔心龍弦情況，提出還是自己去引誘稽查者到終點，被龍弦斥責。"}
,[10533]={["key"]=10533,["storyType"]=1,["name"]="第五章-第29节",["beginId"]=1053301,["id"]=10533,["type"]=1,["section_name"]="暗藍之願（上）",["desc"]="總隊長進入貧民窟後擺脫無人機跟蹤，破壞戴著的制式終端，換成流星工業特製的通訊終端後，閱讀奧蘭治交給自己的晶片中的內容。"}
,[10541]={["key"]=10541,["storyType"]=1,["name"]="第五章-第37节",["beginId"]=1054101,["id"]=10541,["type"]=1,["section_name"]="冰山一角（下）",["desc"]="總隊長從逃生艙離開後，頹廢地在海灘上躺倒，擔心自己無法完成期望中的事情。此時漆黑意識出現，與總隊長對話。"}
,[20812]={["key"]=20812,["storyType"]=10,["name"]="觅己归途活动剧情9",["beginId"]=2081201,["id"]=20812,["type"]=1,["section_name"]="摩擦升溫（下）",["desc"]="新的重建計劃遭到小財迷的強烈反對，這讓刺蝽陷入迷茫之中。總隊長帶著刺蝽去看小財迷的完結活動，借此解開刺蝽多年來的心結。"}
,[20406]={["key"]=20406,["storyType"]=6,["name"]="糖果活动剧情7",["beginId"]=2040601,["id"]=20406,["type"]=1,["section_name"]="絕不單調（上）",["desc"]="計劃永遠趕不上變化——越來越多的人加入其中，走向無法預料。地球人與碎星人的合作，會讓這個劇本變成什麼樣？"}
,[20806]={["key"]=20806,["storyType"]=10,["name"]="觅己归途活动剧情4",["beginId"]=2080601,["id"]=20806,["type"]=1,["section_name"]="風土人情（上）",["desc"]="刺蝽和總隊長接受安娜的招待，小財迷卻在知道刺蝽的身份後產生不滿。當天晚上，總隊長在與小財迷、當地居民的溝通中加深對夜鶯鎮的瞭解。"}
,[20107]={["key"]=20107,["storyType"]=2,["name"]="卡提那个人活动第8节",["beginId"]=2010701,["id"]=20107,["type"]=1,["section_name"]="君王",["desc"]="面對造物的不斷進攻，二人背水一戰，但此刻卻出現了一個期待已久的身影。"}
,[20804]={["key"]=20804,["storyType"]=10,["name"]="觅己归途活动剧情3",["beginId"]=2080401,["id"]=20804,["type"]=1,["section_name"]="歸鄉（下）",["desc"]="刺蝽和總隊長來到夜鶯鎮，發現這裏沒有如期開始重建。之後兩人救下自稱小財迷的小女孩，並從她口中得知了幫派聯盟的存在。在小財迷的帶領下，刺蝽與安娜重逢了。"}
,[10113]={["key"]=10113,["storyType"]=1,["name"]="第一章-第11节",["beginId"]=1011301,["id"]=10113,["type"]=1,["section_name"]="支援",["desc"]="並未認真交手的阿瑞斯面對%s的不斷嘲諷準備展現一些真本事，即將得手之際雅典娜的支援卻打斷了她的計畫。"}
,[10117]={["key"]=10117,["storyType"]=1,["name"]="第一章-第15节",["beginId"]=1011701,["id"]=10117,["type"]=1,["section_name"]="對局",["desc"]="遙遠的奧林匹斯，兩個碎星人正在對弈，奈何目前棋局早已增加新的棋子。另一邊%s等人最後也沒有找到進行曲的蹤跡。"}
,[10121]={["key"]=10121,["storyType"]=1,["name"]="第一章-第19节",["beginId"]=1012101,["id"]=10121,["type"]=1,["section_name"]="燃燒",["desc"]="永遠清理不完的造物使得眾人彈藥消耗速度過快，為了儘快到達寒霜等人所在地，雅典娜燃燒自己展開小心天幕系統助力前行。"}
,[10613]={["key"]=10613,["storyType"]=1,["name"]="第六章-第7节",["beginId"]=1061301,["id"]=10613,["type"]=1,["section_name"]="夜幕之花（下）",["desc"]="殲滅來襲的造物群後，奧諾拉讚賞總隊長，並表示總隊長沒有變成只知戰鬥的機器，這樣很好。阿萊西婭與希恩發生爭執，阿萊西婭嘲諷希恩不懂人類，嘲笑希恩從未真正走入人類的生活。"}
,[10621]={["key"]=10621,["storyType"]=1,["name"]="第六章-第13节",["beginId"]=1062101,["id"]=10621,["type"]=1,["section_name"]="真實身份（上）",["desc"]="希恩逐漸融入難民們的生活，難民卓拉安慰希恩。總隊長等人返回奧爾達基地後，發現有造物潮以及泰坦級造物來襲。"}
,[10629]={["key"]=10629,["storyType"]=1,["name"]="第六章-第21节",["beginId"]=1062901,["id"]=10629,["type"]=1,["section_name"]="深入密巢（上）",["desc"]="留守奧爾達基地的洛貝拉與奧諾拉上校交談，奧諾拉指出洛貝拉對莫爾斯克地區的認知有所偏差，而洛貝拉認為活著才是最重要的事情，兩人出現分歧。"}
,[20802]={["key"]=20802,["storyType"]=10,["name"]="觅己归途活动剧情2",["beginId"]=2080201,["id"]=20802,["type"]=1,["section_name"]="歸鄉（上）",["desc"]="刺蝽和總隊長閑聊時提及刺蝽的家鄉夜鶯鎮。為了調查流入夜鶯鎮的黑市造物，總隊長邀請刺蝽一同前往。"}
,[10645]={["key"]=10645,["storyType"]=1,["name"]="第六章-第32节",["beginId"]=1064501,["id"]=10645,["type"]=1,["section_name"]="深海脈動（上）",["desc"]="得到“源島國際”支援裝置的眾人前往海底基地，進入基地後找到了能源並合開關。高加索十分激動，卻險些被埋伏的機械造物偷襲。"}
,[20412]={["key"]=20412,["storyType"]=6,["name"]="糖果活动剧情13",["beginId"]=2041201,["id"]=20412,["type"]=1,["section_name"]="宇宙飛車（下）",["desc"]="為了讓劇情繼續推演，你和烏斯懷亞成為了渦流手下的一名“水手”。"}
,[21306]={["key"]=21306,["storyType"]=15,["name"]="魔导少女活动剧情5",["beginId"]=2130601,["id"]=21306,["type"]=1,["section_name"]="造物工廠（下）",["desc"]="在消滅造物後，眾人得知該女性的名字是薇薇，是被強迫在這座工廠裡工作的員工，並且還有很多人和她一樣被困在工廠裡。為了儘快解決出其他人，薇薇自告奮勇給大家當嚮導，並且得到了伊根的支持。"}
,[10627]={["key"]=10627,["storyType"]=1,["name"]="第六章-第19节",["beginId"]=1062701,["id"]=10627,["type"]=1,["section_name"]="不可拋卻（下）",["desc"]="進入存放著巨量NOVA結晶的秘密基地後，總隊長見到了阿卡斯的仿生體，並拒絕了阿卡斯關於“重塑計畫”的合作邀請。"}
,[10261]={["key"]=10261,["storyType"]=1,["name"]="第二章-第37节",["beginId"]=1026101,["id"]=10261,["type"]=1,["section_name"]="凝聚態",["desc"]="世界樹內部，有些決心早已許下，現在就是執行決心的時候。"}
,[20003]={["key"]=20003,["storyType"]=2,["name"]="电影活动02-2",["beginId"]=2000301,["id"]=20003,["type"]=2,["section_name"]="第四節指骨",["desc"]="搜尋宿舍外舉止異常的造物。"}
,[20606]={["key"]=20606,["storyType"]=8,["name"]="幻梦逸旅活动剧情7",["beginId"]=2060601,["id"]=20606,["type"]=1,["section_name"]="隱藏的真相",["desc"]="總隊長等人到達地下核心車間後，挾持了幻響的工廠老闆蒂娜出現，要求眾人解除武裝。經過一輪言語迷惑後，G.G.G.成功接近蒂娜，並提出要將發現的大型造物奧帕帶回指揮部基地，蒂娜變得慌張，而不想和蒂娜分離的造物奧帕也進入了暴走。"}
,[10701]={["key"]=10701,["storyType"]=1,["name"]="第七章-第1节",["beginId"]=1070101,["id"]=10701,["type"]=1,["section_name"]="虚妄记忆",["desc"]="伊瓦爾迪替女武神們檢修武裝時出現意外情況，女武神相繼消失，伊瓦爾迪自己也陷入神秘光芒中。諾斯板塊被神秘光暈包圍，前往遊歷的咎瓦尤斯等人也失去聯絡，總隊長權衡後決定自己出發前往諾斯板塊。"}
,[10709]={["key"]=10709,["storyType"]=1,["name"]="第七章-第5节",["beginId"]=1070901,["id"]=10709,["type"]=1,["section_name"]="尤克希爾（下）",["desc"]="在卡提那的帶領下回到宮殿，總隊長從弗麗嘉的口中瞭解關於“尤克希爾”的資訊，並得知通過三重阻隔考驗，收集統治者的盧恩符文的人，可以獲得與奧丁相等的地位。"}
,[10717]={["key"]=10717,["storyType"]=1,["name"]="第七章-第9节",["beginId"]=1071701,["id"]=10717,["type"]=1,["section_name"]="逾越界限（上）",["desc"]="收集到底層所有國度的統治者符文後，總隊長三人返回穆斯貝爾海姆，在伊瓦爾迪的安排下進行休整。半夜總隊長失眠時，在房外遇到了弗麗嘉，兩人談心。"}
,[10725]={["key"]=10725,["storyType"]=1,["name"]="第七章-第16节",["beginId"]=1072501,["id"]=10725,["type"]=1,["section_name"]="鏡中面目",["desc"]="奧丁在房間裏與托爾交談，並說出自己為什麼在失蹤後又重新回歸諾斯板塊，還有建立“尤克希爾”的原因。在最後，奧丁告知自己會選擇托爾接任統治者的真正原因，托爾大受打擊。"}
,[10733]={["key"]=10733,["storyType"]=1,["name"]="第七章-第22节",["beginId"]=1073301,["id"]=10733,["type"]=1,["section_name"]="朽構深淵（下）",["desc"]="與純白成功共鳴後，總隊長抱著昏迷不醒的希恩，在純白的指引下尋找出口。"}
