,[20219]={["key"]=20219,["storyType"]=3,["name"]="蛛影活动剧情19",["beginId"]=2021901,["id"]=20219,["type"]=1,["section_name"]="孩提",["desc"]="在測繪過程中，這個年齡不大的戰士還是在你的面前漏出了一絲孩提的氣息。"}
,[20227]={["key"]=20227,["storyType"]=3,["name"]="蛛影活动剧情27",["beginId"]=2022701,["id"]=20227,["type"]=1,["section_name"]="卵鞘",["desc"]="伊根根據流星工業的數據中，以“特殊機體1號”檢索到了一個移動的兵工廠——巨脈蜻蜓，而此刻它就蟄伏於此。"}
,[10413]={["key"]=10413,["storyType"]=1,["name"]="第四章-第12节",["beginId"]=1041301,["id"]=10413,["type"]=1,["section_name"]="鑄造匠人（下）",["desc"]="熔鑠出現後與鳴刃交談，但很快將註意力移到總隊長身上。對待作為異邦人的總隊長，熔鑠抱有一定的戒心，但在鳴刃的勸說下還是以客人禮儀招待了總隊長。"}
,[20212]={["key"]=20212,["storyType"]=3,["name"]="蛛影活动剧情12",["beginId"]=2021201,["id"]=20212,["type"]=1,["section_name"]="洋樓",["desc"]="洋樓內，輝礫小隊和刃齒小隊碰頭，交換情報後本想在其中大鬧一番，但一個電話打斷了眾人的思考。"}
,[20403]={["key"]=20403,["storyType"]=6,["name"]="糖果活动剧情4",["beginId"]=2040301,["id"]=20403,["type"]=1,["section_name"]="突如其來（下）",["desc"]="清理完造物後，赫拉出面道歉，並道出惡作劇的罪魁禍首——赫爾墨斯。"}
,[20411]={["key"]=20411,["storyType"]=6,["name"]="糖果活动剧情12",["beginId"]=2041101,["id"]=20411,["type"]=1,["section_name"]="宇宙飛車（上）",["desc"]="面對生氣的渦流，最好的安撫方式是和她好好打一場。"}
